#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
BuddyZ Gateway — WorkBuddy(CodeBuddy) / MonkeyCode / CodeArts 一体化反代网关（单文件 GUI）

功能：
  ① CodeBuddy / WorkBuddy 订阅  →  OpenAI 兼容 API   /v1/chat/completions
  ② MonkeyCode 桌面端           →  OpenAI 兼容 API   /v1/chat/completions
  ③ 华为云 CodeArts（码道）     →  OpenAI 兼容 API   /v1/chat/completions
三者内嵌在本文件中，首次运行自动解包到 %LOCALAPPDATA%/BuddyZGateway/runtime。

模式：
  python BuddyZGateway.py                 # 打开 GUI
  python BuddyZGateway.py --selftest      # 无界面自检
  python BuddyZGateway.py --serve         # 无界面三服务模式（--mc-port/--ca-port 可调）
"""

from __future__ import annotations

import base64
import importlib
import importlib.util
import json
import os
import re
import socket
import subprocess
import sys
import threading
import time
import queue
from pathlib import Path

APP_NAME = "BuddyZGateway"
VERSION = "1.7.1"

# ---------------------------------------------------------------------------
# 号池功能总开关
# ---------------------------------------------------------------------------
# 当前设为 False = **屏蔽**（用户反馈该功能还不够完善）。屏蔽时的效果：
#   · GUI 不显示「号池轮转」勾选与「号池…」按钮（入口完全消失，不会被误开）
#   · 无论 settings.json 里存过什么，GUI 启动与 --serve 都强制 pool_enabled=False
#   · 已抓取的号池条目与调度参数仍**保留在 settings 里**，不会丢数据
#   · 通道本身的功能不受影响：mc 走本机桌面端 key、ca 走 DPK/直连临时凭证
# 想恢复：把这里改成 True 即可（引擎 buddyzpool.py 与各通道接线都还在）。
POOL_FEATURE = False

# ---------------------------------------------------------------------------
# 路径
# ---------------------------------------------------------------------------

def _localappdata() -> Path:
    return Path(os.environ.get("LOCALAPPDATA") or (Path.home() / "AppData" / "Local"))


def app_root() -> Path:
    return _localappdata() / APP_NAME


def runtime_dir() -> Path:
    return app_root() / "runtime"


def data_dir() -> Path:
    return app_root() / "data"


def logs_dir() -> Path:
    return app_root() / "data" / "logs"


def is_frozen() -> bool:
    return bool(getattr(sys, "frozen", False))


