# CodeBuddy 凭据检测（轻量，不依赖第三方库）
# ---------------------------------------------------------------------------

def find_cb_auth_file(station: str | None = None) -> Path | None:
    """找 WorkBuddy auth 文件。

    station: "cn" | "intl" | None
      - "cn"     → workbuddy-desktop.info      (国内 www.workbuddy.cn)
      - "intl"   → workbuddy-desktop-ai.info  (国际 www.workbuddy.ai)
      - None     → 兼容旧调用：优先找国际版，找不到再退回国内版
    """
    local = Path(os.environ.get("LOCALAPPDATA") or (Path.home() / "AppData" / "Local"))
    d = local / "CodeBuddyExtension" / "Data" / "Public" / "auth"
    if not d.is_dir():
        return None
    if station == "cn":
        p = d / "workbuddy-desktop.info"
        return p if p.is_file() else None
    if station == "intl":
        p = d / "workbuddy-desktop-ai.info"
        return p if p.is_file() else None
    # station is None: 兼容旧调用（不指定站点时，优先找国际版再退回国内版）
    # 这样既不破坏现有调用，又能让显式指定站点的调用精确生效
    for fname in ("workbuddy-desktop-ai.info", "workbuddy-desktop.info"):
        p = d / fname
        if p.is_file():
            return p
    return None


def read_cb_summary(station: str | None = None) -> dict:
    af = find_cb_auth_file(station)
    if af is None:
        return {"found": False, "station": station}
    try:
        data = json.loads(af.read_text(encoding="utf-8"))
        auth = data.get("auth") or {}
        acct = data.get("account") or {}
        exp = auth.get("expiresAt") or 0
        dom = auth.get("domain") or ""
        # 由 domain 反推实际站点，供 GUI 显示与后端选择（.ai → 国际，其余 → 国内）
        real_station = ("intl" if any(k in dom for k in ("workbuddy.ai", "codebuddy.ai"))
                        else "cn")
        return {
            "found": True,
            "path": str(af),
            "nickname": acct.get("nickname") or "?",
            "enterprise": acct.get("enterpriseName") or "-",
            "domain": dom or "-",
            "station": real_station,
            "expired": time.time() * 1000 >= (exp - 60_000),
            "expires_at": exp,
        }
    except Exception as e:  # noqa: BLE001
        return {"found": True, "path": str(af), "station": station, "error": str(e)}


# ---------------------------------------------------------------------------
# Windows DPI 感知（必须在创建 Tk 窗口之前调用，否则高分屏下文字偏小）
# ---------------------------------------------------------------------------

def enable_windows_dpi_awareness() -> bool:
    if sys.platform != "win32":
        return False
    try:
        import ctypes
        try:
            # Per-Monitor DPI Aware v2 (Win10 1703+)
            ctypes.windll.shcore.SetProcessDpiAwarenessContext(ctypes.c_void_p(-4))
            return True
        except Exception:
            pass
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(2)  # Per-Monitor DPI Aware
            return True
        except Exception:
            pass
        try:
            ctypes.windll.user32.SetProcessDPIAware()  # System DPI Aware (fallback)
            return True
        except Exception:
            pass
    except Exception:
        pass
    return False


def _winstate_path() -> Path:
    """窗口状态文件（尺寸/位置/折叠状态）。"""
    return data_dir() / "ui_window.json"


def save_window_state(root, collapsed: dict, gezura: bool = False) -> None:
    """记下窗口几何与折叠状态，下次启动时原样恢复。

    gezura（最大化）单独记：最大化时 winfo_x/y 是"还原前"的坐标，
    直接存会让下次恢复到一个奇怪的位置。
    """
    try:
        wm = root.wm_state() if hasattr(root, "wm_state") else "normal"
        st = {
            "x": root.winfo_x(), "y": root.winfo_y(),
            "w": root.winfo_width(), "h": root.winfo_height(),
            "zoomed": bool(gezura or wm == "zoomed"),
            "collapsed": {str(k): bool(v) for k, v in (collapsed or {}).items()},
        }
    except Exception:          # noqa: BLE001  窗口可能已销毁
        return
    try:
        p = _winstate_path()
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(st, ensure_ascii=False, indent=2), encoding="utf-8")
    except OSError:
        pass                   # 存不了就算了，不该因此阻止退出


def load_window_state() -> dict:
    """读上次的窗口状态；没有/损坏则返回空 dict。"""
    try:
        d = json.loads(_winstate_path().read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except Exception:          # noqa: BLE001
        return {}


def clamp_window_to_screen(root: "tk.Tk") -> None:
    """把窗口强制移回所在显示器的工作区（扣掉任务栏，多显示器安全）"""
    try:
        import ctypes
        root.update_idletasks()
        # 取窗口所在显示器的工作区 rcWork（已扣除任务栏）
        wa = None
        try:
            user32 = ctypes.windll.user32
            hwnd = root.winfo_id()

            class RECT(ctypes.Structure):
                _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                            ("right", ctypes.c_long), ("bottom", ctypes.c_long)]

            class MONITORINFO(ctypes.Structure):
                _fields_ = [("cbSize", ctypes.c_ulong), ("rcMonitor", RECT),
                            ("rcWork", RECT), ("dwFlags", ctypes.c_ulong)]

            mon = user32.MonitorFromWindow(hwnd, 2)  # MONITOR_DEFAULTTONEAREST
            mi = MONITORINFO()
            mi.cbSize = ctypes.sizeof(MONITORINFO)
            if user32.GetMonitorInfoW(mon, ctypes.byref(mi)):
                wa = (mi.rcWork.left, mi.rcWork.top, mi.rcWork.right, mi.rcWork.bottom)
        except Exception:
            wa = None
        if wa is None:
            # 兜底：主屏全尺寸（至少不跑出屏幕外）
            wa = (0, 0, root.winfo_screenwidth(), root.winfo_screenheight())
        wl, wt, wr, wb = wa
        w = root.winfo_width()
        h = root.winfo_height()
        x = root.winfo_x()
        y = root.winfo_y()
        if x + w > wr:
            x = wr - w
        if y + h > wb:
            y = wb - h
        if x < wl:
            x = wl
        if y < wt:
            y = wt
        # 窗口比工作区还大时，至少保证左上角可见
        x = max(wl, min(x, wr - 50))
        y = max(wt, min(y, wb - 50))
        if (x, y) != (root.winfo_x(), root.winfo_y()):
            root.geometry(f"+{x}+{y}")
    except Exception:
        pass


