# WorkBuddy 两版靠 **exe 名**区分（目录名无法区分）
WB_STATION_EXES = {
    "cn": ("WorkBuddy.exe",),        # 国内：C:\Program Files\WorkBuddy
    "intl": ("WorkBuddyAI.exe",),    # 国际：C:\Program Files\WorkBuddyAI
}
WB_STATION_LABEL = {"cn": "国内", "intl": "国际"}
# 两版各自的 auth 文件（同目录、不同文件名，因此可以同时登录互不覆盖）
WB_AUTH_FILES = {"cn": "workbuddy-desktop.info",       # 国内 www.workbuddy.cn
                 "intl": "workbuddy-desktop-ai.info"}  # 国际 www.workbuddy.ai


def _kind_profiles(kind: str) -> list:
    return _INSTALL_PROFILES.get(kind) or _INSTALL_PROFILES["ca"]


def _kind_exe_names(kind: str) -> tuple:
    """该通道所有来源的主程序名（按优先级去重）。"""
    out: list[str] = []
    for _hints, exes in _kind_profiles(kind):
        for e in exes:
            if e not in out:
                out.append(e)
    return tuple(out)


def resolve_install_input(path: str, kind: str) -> str:
    """用户选择的 exe 或文件夹 → 归一化：文件夹则自动定位其中的主程序 exe。

    ca 同时认 codearts-agent.exe（桌面端）和 Code.exe（VS Code），
    所以直接把 VS Code 的安装文件夹粘进来也能定位到 Code.exe。
    """
    p = (path or "").strip().strip('"')
    if not p:
        return ""
    if p.lower().endswith(".exe"):
        return p
    if Path(p).is_dir():
        for en in _kind_exe_names(kind):
            c = Path(p) / en
            if c.is_file():
                return str(c)
        try:
            for x in sorted(Path(p).glob("*.exe")):
                return str(x)
        except OSError:
            pass
    return p


def _scan_dirs_for(bases: list, hints: tuple, exe_names: tuple, dirs_cand: list) -> str:
    for b in bases:
        if not b:
            continue
        try:
            for name in os.listdir(b):
                low = str(name).lower()
                if any(h in low for h in hints):
                    d = os.path.join(b, name)
                    if os.path.isdir(d):
                        for en in exe_names:
                            p = os.path.join(d, en)
                            if os.path.isfile(p):
                                return p
                        dirs_cand.append(d)
        except OSError:
            continue
    return ""


def _scan_registry_for(hints: tuple, exe_names: tuple, dirs_cand: list) -> str:
    try:
        import winreg
    except ImportError:
        return ""
    roots = [
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_CURRENT_USER, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
    ]
    for hive, sub in roots:
        try:
            root_key = winreg.OpenKey(hive, sub)
        except OSError:
            continue
        with root_key:
            i = 0
            while True:
                try:
                    key_name = winreg.EnumKey(root_key, i)
                except OSError:
                    break
                i += 1
                try:
                    with winreg.OpenKey(root_key, key_name) as sk:
                        try:
                            disp, _ = winreg.QueryValueEx(sk, "DisplayName")
                        except OSError:
                            continue
                        if not any(h in str(disp).lower() for h in hints):
                            continue
                        for attr in ("DisplayIcon", "InstallLocation"):
                            try:
                                val, _ = winreg.QueryValueEx(sk, attr)
                            except OSError:
                                continue
                            val = str(val).split(",")[0].strip().strip('"')
                            if not val:
                                continue
                            if val.lower().endswith(".exe"):
                                if os.path.isfile(val):
                                    return val
                                val = os.path.dirname(val)
                            if val and os.path.isdir(val):
                                for en in exe_names:
                                    p = os.path.join(val, en)
                                    if os.path.isfile(p):
                                        return p
                                dirs_cand.append(val)
                except OSError:
                    continue
    return ""


def find_install(kind: str, station: str | None = None) -> str:
    """自动搜索本机安装位置：Program Files 系列 + 注册表卸载项。

    kind: 'wb' | 'mc' | 'ca' | 'rc' | 'lo'。按画像优先级返回第一个命中：
    ca 先找华为云 CodeArts 桌面端，桌面端不在才退回 VS Code。

    station: 只有 'wb' 用得上 —— "cn" 只找 WorkBuddy.exe（国内），
    "intl" 只找 WorkBuddyAI.exe（国际）。两版安装目录名都含 "workbuddy"，
    不指定站点时无法区分，只能靠 exe 名。
    """
    bases = [
        os.environ.get("ProgramFiles", r"C:\Program Files"),
        os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"),
        os.environ.get("ProgramW6432", r"C:\Program Files"),
        os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs"),
        os.environ.get("LOCALAPPDATA", ""),
    ]
    profiles = _kind_profiles(kind)
    if kind == "wb" and station in WB_STATION_EXES:
        profiles = [(("workbuddy", "codebuddy"), WB_STATION_EXES[station])]
    dirs_cand: list[str] = []
    for hints, exe_names in profiles:
        hit = _scan_dirs_for(bases, hints, exe_names, dirs_cand)
        if hit:
            return hit
        hit = _scan_registry_for(hints, exe_names, dirs_cand)
        if hit:
            return hit
    return dirs_cand[0] if dirs_cand else ""


# ---------------------------------------------------------------------------
# 服务包装（uvicorn 线程）
# ---------------------------------------------------------------------------

class ProxyService:
    def __init__(self, key: str, title: str):
        self.key = key
        self.title = title
        self.server = None
        self.thread = None
        self.error: str | None = None
        self.started_at: float | None = None

    @property
    def running(self) -> bool:
        return (self.server is not None and self.thread is not None
                and self.thread.is_alive() and not self.server.should_exit)

    def start(self, app_obj, host: str, port: int):
        import uvicorn
        cfg = uvicorn.Config(app_obj, host=host, port=port, log_level="info", lifespan="on")
        self.server = uvicorn.Server(cfg)
        self.error = None
        self.started_at = time.time()
        self.thread = threading.Thread(target=self._serve, name=f"{self.key}-uvicorn", daemon=True)
        self.thread.start()

    def _serve(self):
        try:
            self.server.run()
        except Exception as e:  # noqa: BLE001
            self.error = f"{type(e).__name__}: {e}"

    def stop(self, timeout=10.0):
        if self.server is not None:
            self.server.should_exit = True
        if self.thread is not None:
            self.thread.join(timeout)
        self.server = None
        self.thread = None
        self.started_at = None


