# 启动耗时探针：只在 BZG_TIMING=1 时打印，平时零开销、零输出。
# 用来定位"打开界面卡"到底卡在哪一段（改启动流程前先量，别猜）。
_PROC_T0 = time.perf_counter()
_TIMING = bool(os.environ.get("BZG_TIMING"))


def _mark(label: str) -> None:
    if _TIMING:
        # 注意 perf_counter 返回的是**秒**，乘 1000 才是毫秒
        print(f"[timing] {label}: {(time.perf_counter() - _PROC_T0) * 1000:.0f}ms",
              flush=True)


def run_gui(smoke: bool = False):
    import tkinter as tk
    from tkinter import ttk, messagebox

    log_q: "queue.Queue[tuple]" = queue.Queue()
    tee = Tee()

    settings = load_settings()
    os.environ["BUDDYZ_DATA_DIR"] = str(data_dir())
    _mark("settings 就绪")
    services = {"cb": ProxyService("cb", "CodeBuddy→OpenAI"),
                "mc": ProxyService("mc", "MonkeyCode→OpenAI"),
                "ca": ProxyService("ca", "CodeArts→OpenAI"),
                "rc": ProxyService("rc", "Raccoon→OpenAI"),
                "lo": ProxyService("lo", "Loomy→OpenAI")}

    # ---------------- 日志 ----------------
    logfile = logs_dir() / "gui.log"
    logfile.parent.mkdir(parents=True, exist_ok=True)

    _logf = {"fh": None, "n": 0}

    def _filelog(line: str):
        """常开句柄 + 每 100 行才 flush/查大小。
        原来每行都 open+stat+close，日志量大时是主要开销之一。"""
        try:
            st = _logf
            if st["fh"] is None or getattr(st["fh"], "closed", False):
                if logfile.exists() and logfile.stat().st_size > 2_000_000:
                    logfile.write_text("", encoding="utf-8")
                st["fh"] = open(logfile, "a", encoding="utf-8")
                st["n"] = 0
            st["fh"].write(line + "\n")
            st["n"] += 1
            if st["n"] % 100 == 0:
                st["fh"].flush()
                if logfile.stat().st_size > 2_000_000:
                    st["fh"].close()
                    st["fh"] = None
        except OSError:
            pass

    def emit(line: str):
        line = strip_ansi(line.rstrip())
        if not line:
            return
        stamped = f"[{ts()}] {line}"
        _filelog(stamped)
        log_q.put(("log", stamped))

    tee.install(lambda s: [emit(x) for x in s.splitlines()])

    class _UI:
        @staticmethod
        def ui(fn, *a):
            log_q.put(("call", (fn, a)))

    ui = _UI().ui

    # 高分屏优化：必须在创建 Tk 窗口【之前】开启 DPI 感知，
    # 否则 Windows 按 96dpi 虚拟化渲染，150%/200% 缩放屏上文字会明显偏小。
    enable_windows_dpi_awareness()

    _mark("进入窗口构建")
    root = tk.Tk()
    # 构建期间让窗口完全透明：Tk 每 pack 一批控件就可能重绘一次，用户会看到
    # 界面"一格一格长出来"，明明总耗时没变，体感却像卡住。alpha=0 时窗口仍有
    # 正常的 HWND 与位置（所以 clamp_window_to_screen 照常工作），建完再显形。
    try:
        root.attributes("-alpha", 0.0)
    except Exception:      # noqa: BLE001  个别平台不支持 alpha
        pass
    _mark("Tk() 创建完成")
    root.title(f"{APP_NAME} · 反代网关(WorkBuddy/MonkeyCode) v{VERSION}")
    try:
        import ctypes
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(APP_NAME)
    except Exception:
        pass

    try:
        dpi = root.winfo_fpixels("1i")
    except Exception:
        dpi = 96.0
    scale = max(1.0, min(3.0, dpi / 96.0))
    root.tk.call("tk", "scaling", dpi / 72.0)
    # 恢复上次窗口状态：有记录就用记录的尺寸/位置，否则用默认尺寸。
    # 位置先不在这里设 —— 那时控件还没建，winfo 尺寸不准；统一放到建完之后。
    _ws = load_window_state()
    _prev = {}
    try:
        w, h = int(_ws.get("w") or 0), int(_ws.get("h") or 0)
    except (TypeError, ValueError):
        w = h = 0
    if w >= 400 and h >= 300:
        root.geometry(f"{w}x{h}")
    else:
        root.geometry(f"{int(920 * scale)}x{int(800 * scale)}")
    root.minsize(int(860 * scale), int(640 * scale))

    style = ttk.Style(root)
    try:
        style.theme_use("vista")
    except Exception:
        pass

    # ------------------------------------------------------------------
    # 全局字号系统：命名字体 + 百分比缩放（50%~200%）
    # ------------------------------------------------------------------
    # 用 tkinter.font.Font 命名字体而不是到处写 ("Microsoft YaHei UI", 7) 元组：
    # 命名对象被所有控件共享，控件只要引用它就能拿到统一字体。
    # 字号固定：界面 6pt（把垂直空间让给运行日志），等宽日志 7pt。
    import tkinter.font as _tkfont

    UI_BASE_SIZE = 6
    MONO_BASE_SIZE = 7

    F_UI = _tkfont.Font(family="Microsoft YaHei UI", size=UI_BASE_SIZE)
    F_UI_BOLD = _tkfont.Font(family="Microsoft YaHei UI", size=UI_BASE_SIZE, weight="bold")
    F_MONO = _tkfont.Font(family="Consolas", size=MONO_BASE_SIZE)
    F_STATUS = _tkfont.Font(family="Microsoft YaHei UI", size=UI_BASE_SIZE + 4, weight="bold")

    def _setup_fonts() -> None:
        """把统一样式落到 ttk 与 Tk 内建命名字体上（只调用一次，不做尺寸切换）。

        ttk 走 style.configure；经典 tk 控件（Text/Listbox/菜单…）走 Tk 内建
        命名字体 —— 两边都指到上面这批，界面字体才不会有的变有的不变。
        """
        for _nm in ("TkDefaultFont", "TkTextFont", "TkMenuFont", "TkHeadingFont",
                    "TkTooltipFont", "TkSmallCaptionFont", "TkIconFont"):
            try:
                _tkfont.nametofont(_nm).configure(family="Microsoft YaHei UI",
                                                  size=UI_BASE_SIZE)
            except Exception:      # noqa: BLE001  某些 Tk 精简发行版没有这些字体
                pass
        style.configure(".", font=F_UI)
        style.configure("TLabelframe.Label", font=F_UI_BOLD)
        # 注：不再 option_add("*Font") —— 它会让 Tk 给所有控件类重算资源（实测几十 ms），
        # 而 ttk 已由上面的 style 覆盖、经典控件都显式传了 F_UI/F_MONO，
        # 全局默认字体也已通过 TkDefaultFont 等内建命名字体设好，属于重复劳动。

    _setup_fonts()
    _mark("字体/样式就绪")

    # ①~⑤ 通道名用蓝色。注意：不能给 ttk.LabelFrame 配 style 再设
    # foreground —— vista 主题会忽略 LabelFrame.Label 的前景色（已像素级实测：
    # 该写法渲染出的蓝色像素为 0）。可靠做法是 labelwidget 挂一个 ttk.Label，
    # ttk.Label 的 foreground 是生效的。
    CHAN_TITLE_FONT = F_UI_BOLD

    # 折叠开关登记表：{LabelFrame 路径: toggle()}，供 --uismoke 做真实折叠断言
    _COLLAPSE: dict = {}
    # 各面板当前是否折叠（{LabelFrame 路径: bool}）→ 退出时存盘，下次启动恢复
    _COLLAPSE_STATE: dict = {}

    def _wire_collapse(lf, arrow):
        """给 LabelFrame 接上「点箭头折叠/展开」的行为。

        折叠 = 把内部**所有内容** pack_forget（只剩标题栏），展开时按原参数放回。
        注意 pack_info() 里带 'in'（父窗口路径），pack() 不接受它，必须白名单过滤；
        并且要把 labelwidget（标题栏自己）排除掉，否则会把标题也折叠没。
        """
        st = {"collapsed": False, "saved": []}
        _KEYS = ("side", "fill", "expand", "anchor", "padx", "pady", "ipadx", "ipady")

        def _hdr_height() -> int:
            """折叠后 LabelFrame 应保留的高度 = 标题栏高度（+ padding 4×2）。

            必须显式给高度：`pack_forget()` 只是让子控件不再参与布局，
            ttk.LabelFrame 的**请求高度不会跟着收缩**（实测 forget 前后
            reqheight 完全一样），下面的面板因此不会上移 —— 这正是
            "看着像只是把内容藏起来、没省出空间"的原因。
            """
            try:
                _lw = lf.nametowidget(lf.cget("labelwidget"))
                return max(16, _lw.winfo_reqheight() + 8)
            except Exception:      # noqa: BLE001
                return 26

        def toggle(_e=None):
            if not st["collapsed"]:
                try:
                    lw = str(lf.cget("labelwidget") or "")
                except Exception:      # noqa: BLE001
                    lw = ""
                st["saved"] = []
                for w in lf.winfo_children():
                    if lw and str(w) == lw:
                        continue       # 标题栏本身不隐藏
                    try:
                        st["saved"].append((w, w.pack_info()))
                        w.pack_forget()
                    except Exception:  # noqa: BLE001  非 pack 布局的控件跳过
                        continue
                # 关掉尺寸传播并写死小高度 —— 两个一起才收得下去
                try:
                    lf.pack_propagate(False)
                    lf.configure(height=_hdr_height())
                except Exception:      # noqa: BLE001
                    pass
                st["collapsed"] = True
                _COLLAPSE_STATE[str(lf)] = True
                arrow.configure(text="▶")
            else:
                for w, info in st["saved"]:
                    kw = {k: info[k] for k in _KEYS if k in info}
                    try:
                        w.pack(**kw)
                    except Exception:  # noqa: BLE001
                        pass
                st["saved"] = []
                # 恢复自适应：`pack_propagate(True)` 与 `height=0` **必须成对**——
                # 只设 height=0 实测无效（仍停在折叠高度），只开 propagate 也会
                # 保留旧 height。
                try:
                    lf.pack_propagate(True)
                    lf.configure(height=0)
                except Exception:      # noqa: BLE001
                    pass
                st["collapsed"] = False
                _COLLAPSE_STATE[str(lf)] = False
                arrow.configure(text="▼")
            for fn in (lf.update_idletasks,):
                try:
                    fn()
                except Exception:      # noqa: BLE001
                    pass
            # 折叠/展开是**用户主动操作**：滚动区必须立刻重算，不能等去抖队列
            # （否则下面的面板虽然上移了，canvas 的滚动范围还是旧的 → 看上去像
            #  "只是把内容藏起来"，没真正省出空间）。
            # 先强制复位 pending 再直接执行，末尾再补一次 —— Tk 的几何计算分两轮
            # idle 收敛，只算一次会差出标题栏那一行的高度。
            _force_sync_size()
            try:
                canvas.after(80, _force_sync_size)
            except Exception:          # noqa: BLE001
                pass

        arrow.bind("<Button-1>", toggle)
        _COLLAPSE[str(lf)] = toggle
        return toggle

    def chan_title(parent, text: str, color: str = "#0a58ca",
                   station=None, on_change=None, station_label: str = "版本",
                   collapsible: bool = False):
        """面板标题（彩色 ttk.Label），配合 labelwidget 使用。

        collapsible=True：在标题**最前面**加 ▼/▶ 箭头，点一下折叠成"只剩标题"，
        再点展开。此时 parent 必须传 **LabelFrame 本身**（调用方要先建
        LabelFrame、再建标题、最后 `lf.configure(labelwidget=box)`），
        因为折叠逻辑需要操作 LabelFrame 里的内容。

        传入 station（StringVar）时，把「版本 自动/国内/国际」单选按钮
        **并排放在标题同一行**，省掉一整行垂直空间给下面的内容。

        语义（三通道统一）：
          自动 = 跟随本机当前登录（cb 取最近活跃、mc 看 server 字段、ca 读插件站点）
          国内 / 国际 = 强制用**该版本账号**的凭据与端点（两版可同时登录，互不干扰）
        切换后需重启该通道服务才生效（回调里会提示）。
        """
        box = ttk.Frame(parent)
        if collapsible:
            _ar = ttk.Label(box, text="▼", font=CHAN_TITLE_FONT,
                            foreground="#0a58ca", cursor="hand2")
            _ar.pack(side="left", padx=(0, 3))
            _wire_collapse(parent, _ar)
        ttk.Label(box, text=text, foreground=color, font=CHAN_TITLE_FONT).pack(side="left")
        if station is not None:
            ttk.Label(box, text=f"　{station_label}",
                      font=CHAN_TITLE_FONT).pack(side="left", padx=(12, 0))
            for val, txt in (("auto", "自动"), ("cn", "国内"), ("intl", "国际")):
                ttk.Radiobutton(box, text=txt, value=val, variable=station,
                                command=on_change or (lambda: None)
                                ).pack(side="left", padx=(4, 0))
        return box

    # ④ 「测试」按钮的颜色反馈：通过=绿 / 失败=红。
    # 外观保持 ttk 原生（和「启动/停止」完全一致），只通过自定义 style 换字色。
    # 注意 ttk.Button 不接受 foreground 参数，必须走 style；
    # 实测 vista 主题下 style 的 foreground 对 Button 是生效的（LabelFrame 则不然）。
    style.configure("TestOk.TButton", foreground="#1a7f37")
    style.configure("TestErr.TButton", foreground="#c0392b")
    _test_btns: dict = {}

    def _test_begin(key: str) -> None:
        """开始测试：按钮恢复默认外观"""
        b = _test_btns.get(key)
        if b is not None:
            ui(lambda: b.configure(style="TButton"))

    def _test_done(key: str, ok: bool) -> None:
        """测试结束：通过变绿，不通过变红"""
        b = _test_btns.get(key)
        if b is not None:
            ui(lambda: b.configure(style="TestOk.TButton" if ok else "TestErr.TButton"))

    wl = int(860 * scale)  # 说明文字换行宽度（随 DPI 缩放）

    def make_led(parent):
        sz = max(12, int(12 * scale))
        c = tk.Canvas(parent, width=sz, height=sz, highlightthickness=0)
        c.create_oval(1, 1, sz - 1, sz - 1, fill="#999", outline="", tags="o")
        return c

    # ------------------------------------------------------------------
    # 整窗可滚动：内容比窗口高时，右侧出现滚动条（也和"字号调大"配合）
    # ------------------------------------------------------------------
    # 做法是经典的 Canvas + 内嵌 Frame：
    #   outer(填满 root) └ canvas(左，可滚) + vsb(右，滚动条)
    #   canvas 里放 inner，所有面板都挂到 inner 上（不再直接挂 root）。
    # 这样无论把字号调到多大、或者窗口被拉得多小，都能靠滚动条看到全部内容。
    outer = ttk.Frame(root)
    outer.pack(fill="both", expand=True)
    # canvas 底色取 ttk 主题背景：不然折叠后内容区变矮，下方露出的
    # canvas 底色与面板背景不同色，看着就像"留了一块没缩小的空白"。
    try:
        _theme_bg = style.lookup("TFrame", "background") or root.cget("bg")
    except Exception:              # noqa: BLE001
        _theme_bg = root.cget("bg")
    canvas = tk.Canvas(outer, highlightthickness=0, bd=0, bg=_theme_bg)
    vsb = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
    canvas.configure(yscrollcommand=vsb.set)
    vsb.pack(side="right", fill="y")
    canvas.pack(side="left", fill="both", expand=True)

    inner = ttk.Frame(canvas)
    _inner_win = canvas.create_window((0, 0), window=inner, anchor="nw")

    # ------------------------------------------------------------------
    # 尺寸同步（去抖）：一次 resize 会连发几十上百个 <Configure>，
    # 每次都 itemconfigure+scrollregion 会让 Tk 把全部子控件重排一遍 —— 这就是
    # "拖拽窗口明显卡顿"的来源。用 40ms 合并窗口把同一阵 resize 合成一次。
    # ------------------------------------------------------------------
    # 同时让内容区**至少填满视口**：
    #   · 高度 = max(内容请求高, 视口高) → 折叠后不会在下方露出 canvas 底色；
    #   · 多余空间由「运行日志」expand 吃掉（折叠省出的地方立刻多显示几行日志）。
    # 这里用 inner.winfo_reqheight()（内容的自然高）而不是 canvas.bbox()：
    # bbox 依赖 inner 当前高度，会和自己形成循环。
    _size_job = {"pending": False}
    _size_last = {"w": -1, "h": -1}     # 上次应用的尺寸，用来识别"自己引发的 Configure"

    def _do_sync_size():
        _size_job["pending"] = False
        try:
            w = max(1, canvas.winfo_width())
            h = max(inner.winfo_reqheight(), canvas.winfo_height())
            # **关键**：改 inner 尺寸本身会让 inner 再发一个 <Configure>，又回到
            # `_sync_size` 排队 → 40ms 后再改一次 → 无限自我循环，拖拽窗口时就是
            # 持续重排（实测平均 30ms/次）。尺寸没变就什么都不做，直接打破循环。
            if w == _size_last["w"] and h == _size_last["h"]:
                return
            _size_last["w"], _size_last["h"] = w, h
            _t0 = time.perf_counter()
            canvas.itemconfigure(_inner_win, width=w, height=h)
            canvas.configure(scrollregion=(0, 0, w, h))
            _do_sync_size.cost = (time.perf_counter() - _t0) * 1000   # 供自检统计
        except Exception:          # noqa: BLE001  窗口销毁中
            pass

    def _sync_size(_e=None):
        if _size_job["pending"]:
            return
        _size_job["pending"] = True
        try:
            # 16ms ≈ 一帧：既能把一次拖拽里连续几十个 <Configure> 合并掉，
            # 又不会让内容跟着窗口"迟一拍"（40ms 时能感觉到滞后）。
            canvas.after(16, _do_sync_size)
        except Exception:          # noqa: BLE001
            _size_job["pending"] = False

    # 兼容旧名（折叠逻辑与自检里都引用它）
    _do_sync_scrollregion = _do_sync_size
    _sync_scrollregion = _sync_size

    def _force_sync_size():
        """立刻按当前内容重排（跳过 40ms 去抖与尺寸去重）。

        折叠/展开、自检这类**必须马上看到结果**的场合用它。
        """
        _size_job["pending"] = False
        _size_last["w"] = _size_last["h"] = -1
        _do_sync_size()

    # inner 的 <Configure>（内容变化）与 canvas 的 <Configure>（窗口 resize）
    # 走**同一个**去抖入口：两者都会引起整棵控件树重排，合并处理。
    inner.bind("<Configure>", _sync_size)
    canvas.bind("<Configure>", _sync_size)
    _mark("滚动容器就绪")

    def _wheel(e):
        """鼠标滚轮滚整窗。

        指针停在「运行日志」/模型列表这类**自带滚动**的控件上时不拦截，
        否则用户想滚日志却把整个窗口滚跑了。
        """
        w = root.winfo_containing(e.x_root, e.y_root)
        while w is not None:
            if isinstance(w, (tk.Text, tk.Listbox)):
                return None
            try:
                w = w.master
            except Exception:      # noqa: BLE001
                break
        canvas.yview_scroll(int(-e.delta / 120), "units")
        return "break"

    root.bind_all("<MouseWheel>", _wheel)

    # ---------------- 顶部 ----------------
    # 原来「一键启动/全部停止/检测本地环境」独占一行，现在和开关、依赖按钮并成一行，
