    ttk.Button(opt, text="■ 全部停止", command=lambda: threading.Thread(target=stop_all, daemon=True).start()).pack(side="right", padx=4)
    ttk.Button(opt, text="▶ 一键启动", command=lambda: threading.Thread(target=start_all, daemon=True).start()).pack(side="right", padx=4)

