    def _ca_station_changed():
        """切换「版本」→ 立刻改站点判定（不必重启服务）。

        ca 的站点只被 _current_station() 读一次再派生所有端点，改 CONFIG 即生效。
        """
        _persist()
        _st = None if ca_station.get() == "auto" else ca_station.get()
        emit(f"[ca] 版本 → {ca_station.get()}")
        try:
            ca = sys.modules.get("codearts2openai")
            if ca is not None:
                ca.CONFIG["station"] = _st
                emit(f"[ca] 已切换 · 站点={ca._current_station()}"
                     f" · 对话域={ca._snap()}")
            else:
                emit("[ca] 服务未启动，下次启动时生效")
        except Exception as e:  # noqa: BLE001
            emit(f"[ca] 切换失败：{type(e).__name__}: {e}")
        ui(refresh_ca_info)
        ui(lambda: refresh_creds(True))

