    def _log_copy_selection():
        try:
            sel = log_text.get("sel.first", "sel.last")
        except Exception:
            sel = ""
        if sel:
            root.clipboard_clear()
            root.clipboard_append(sel)

    def _log_select_all():
        try:
            log_text.tag_add("sel", "1.0", "end-1c")
        except Exception:
            pass

    log_menu = tk.Menu(root, tearoff=0)
    log_menu.add_command(label="复制选中", command=_log_copy_selection)
    log_menu.add_command(label="全选", command=_log_select_all)
    log_menu.add_separator()
    log_menu.add_command(label="清空日志", command=lambda: (log_text.configure(state="normal"),
                                                             log_text.delete("1.0", "end"),
                                                             log_text.configure(state="disabled")))

    def _log_popup(event):
        try:
            log_menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                log_menu.grab_release()
            except Exception:
                pass

    log_text.bind("<Button-3>", _log_popup)

    def clear_log():
        log_text.configure(state="normal")
