    # ---------------- Hermes Agent 集成 ----------------
    def hermes_profile_homes() -> list:
        """本机全部 Hermes profile 目录（默认 + profiles/*，以存在 config.yaml 为准）"""
        homes = []
        cands = [Path.home() / ".hermes",
                 _localappdata() / "hermes"]
        profdir = _localappdata() / "hermes" / "profiles"
        try:
            for sub in sorted(profdir.iterdir()):
                if sub.is_dir():
                    cands.append(sub)
        except OSError:
            pass
        seen = set()
        for h in cands:
            try:
                key = str(h.resolve())
            except OSError:
                key = str(h)
            if key in seen:
                continue
            seen.add(key)
            if (h / "config.yaml").is_file():
                homes.append(h)
        return homes

    def hermes_config_path() -> Path:
        # 活动 profile 优先（桌面端/HERMES_HOME），回退默认 ~/.hermes
        home = os.environ.get("HERMES_HOME", "").strip()
        if home:
            return Path(home) / "config.yaml"
        return Path.home() / ".hermes" / "config.yaml"

    def hermes_env_path(home=None) -> Path:
        base = Path(home) if home else hermes_config_path().parent
        return base / ".env"

    def read_hermes_config(path=None) -> dict | None:
        p = Path(path) if path else hermes_config_path()
        if not p.is_file():
            return None
        try:
            import yaml
            return yaml.safe_load(p.read_text(encoding="utf-8")) or {}
        except Exception as e:
            emit(f"[hermes] 读取配置失败({p}): {e}")
            return None

    def write_hermes_config(cfg: dict, path=None) -> bool:
        p = Path(path) if path else hermes_config_path()
        try:
            import yaml
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(yaml.safe_dump(cfg, allow_unicode=True, sort_keys=False), encoding="utf-8")
            return True
        except Exception as e:
            emit(f"[hermes] 写入配置失败({p}): {e}")
            return False

    def _buddyz_key_env(pid: str) -> str:
        # 与 hermes 官方 custom_endpoint_key_env 同规则
        slug = re.sub(r"[^A-Z0-9]+", "_", pid.upper()).strip("_")
        return f"HERMES_CUSTOM_{slug}_API_KEY" if slug else "HERMES_CUSTOM_API_KEY"

    def _ensure_hermes_env_key(var: str, val: str, home=None):
        """key 写入 profile .env（无查重追加）；对应 hermes 的 key_env 机制"""
        p = hermes_env_path(home)
        try:
            cur = p.read_text(encoding="utf-8") if p.is_file() else ""
            if re.search(rf"(?m)^{re.escape(var)}\s*=", cur):
                return
            if cur and not cur.endswith("\n"):
                cur += "\n"
            cur += f"{var}={val}\n"
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(cur, encoding="utf-8")
        except OSError as e:  # noqa: BLE001
            emit(f"[hermes] 写入 .env 失败: {e}")

    def _buddyz_hermes_entries(host: str, cb_p: int, mc_p: int, ca_p: int, rc_p: int, lo_p: int) -> dict:
        """providers.<id> 条目（桌面端自定义端点面板认这个 schema）"""
        def _entry(pid: str, port: int, key: str, models: list):
            models = models or ["auto"]
            return {
                "name": pid,
                "base_url": f"http://{host}:{port}/v1",
                "model": models[0],
                "discover_models": True,
                "models": {m: {} for m in models[:12]},
                "key_env": _buddyz_key_env(pid),
            }
        return {
            "buddyz-cb": _entry("buddyz-cb", cb_p, "cb", eff_models("cb")),
            "buddyz-mc": _entry("buddyz-mc", mc_p, "mc", eff_models("mc")),
            "buddyz-ca": _entry("buddyz-ca", ca_p, "ca", eff_models("ca")),
            "buddyz-rc": _entry("buddyz-rc", rc_p, "rc", eff_models("rc")),
            "buddyz-lo": _entry("buddyz-lo", lo_p, "lo", eff_models("lo")),
        }

    def sync_to_hermes():
        homes = hermes_profile_homes()
        if not homes:
            emit("[hermes] 未找到任何 Hermes profile 配置，请确认 Hermes Agent 已安装")
            return
        host = _host()
        cb_p = int(cb_port.get()) if cb_port.get().strip().isdigit() else 8787
        mc_p = int(mc_port.get()) if mc_port.get().strip().isdigit() else 9000
        ca_p = int(ca_port.get()) if ca_port.get().strip().isdigit() else 9100
        rc_p = int(rc_port.get()) if rc_port.get().strip().isdigit() else 9200
        lo_p = int(lo_port.get()) if lo_port.get().strip().isdigit() else 9400

        # 只同步勾选的 provider
        all_entries = _buddyz_hermes_entries(host, cb_p, mc_p, ca_p, rc_p, lo_p)
        selected = {}
        names = []
        if hr_sync_cb.get():
            selected["buddyz-cb"] = all_entries["buddyz-cb"]
            names.append("WorkBuddy")
        if hr_sync_mc.get():
            selected["buddyz-mc"] = all_entries["buddyz-mc"]
            names.append("MonkeyCode")
        if hr_sync_ca.get():
            selected["buddyz-ca"] = all_entries["buddyz-ca"]
            names.append("华为云")
        if hr_sync_rc.get():
            selected["buddyz-rc"] = all_entries["buddyz-rc"]
            names.append("小浣熊")
        if hr_sync_lo.get():
            selected["buddyz-lo"] = all_entries["buddyz-lo"]
            names.append("Loomy")
        if not selected:
            emit("[hermes] 未勾选任何反代，请先勾选要同步的服务")
            return

        ok_homes = []
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            # 先移除所有 buddyz-*，再写入选中的
            for k in [k for k in providers if str(k).startswith("buddyz-")]:
                providers.pop(k, None)
            providers.update(selected)
            cfg["providers"] = providers
            # 占位 key 进各 profile .env（本地反代不校验，hermes 侧要求 key 存在）
            for pid in selected:
                _ensure_hermes_env_key(_buddyz_key_env(pid), "local-noauth", home)
            if write_hermes_config(cfg, home / "config.yaml"):
                ok_homes.append(home.name)
        if ok_homes:
            emit(f"[hermes] 已同步 {len(selected)} 个 provider（{' / '.join(names)}）到 {len(ok_homes)} 个 profile：{', '.join(ok_homes)}")
            hermes_status_label.config(foreground="#28a745")
            hermes_status_var.set(f"已同步（{' / '.join(names)}）×{len(ok_homes)}配置")
            _persist()
        else:
            emit("[hermes] 同步失败")

    def remove_from_hermes():
        homes = hermes_profile_homes()
        if not homes:
            emit("[hermes] 未找到任何 Hermes profile 配置")
            return
        total = 0
        touched = []
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            buddyz_keys = [k for k in providers if str(k).startswith("buddyz-")]
            if not buddyz_keys:
                continue
            for k in buddyz_keys:
                providers.pop(k, None)
            cfg["providers"] = providers
            if write_hermes_config(cfg, home / "config.yaml"):
                total += len(buddyz_keys)
                touched.append(home.name)
        if total == 0:
            emit("[hermes] 所有 profile 中均未找到 BuddyZGateway 的 provider")
            hermes_status_var.set("未同步")
            hermes_status_label.config(foreground="#888")
        else:
            emit(f"[hermes] 已从 {len(touched)} 个 profile 移除 {total} 个 provider（.env 占位 key 保留）：{', '.join(touched)}")
            hermes_status_label.config(foreground="#888")
            hermes_status_var.set("未同步")

    def refresh_hermes_status():
        homes = hermes_profile_homes()
        if not homes:
            hermes_status_var.set("未检测到 Hermes")
            hermes_status_label.config(foreground="#888")
            return
        buddyz_names = []
        name_map = {"buddyz-cb": "WorkBuddy", "buddyz-mc": "MonkeyCode", "buddyz-ca": "华为云", "buddyz-rc": "小浣熊"}
        hit_homes = 0
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            found_here = False
            for k in providers:
                if str(k) in name_map:
                    if name_map[str(k)] not in buddyz_names:
                        buddyz_names.append(name_map[str(k)])
                    found_here = True
            if found_here:
                hit_homes += 1
        if buddyz_names:
            hermes_status_var.set(f"已同步（{' / '.join(buddyz_names)}）×{hit_homes}/{len(homes)}配置")
            hermes_status_label.config(foreground="#28a745")
        else:
            hermes_status_var.set("未同步")
            hermes_status_label.config(foreground="#888")

    def eff_models(key: str) -> list:
        """当前生效的暴露模型列表。空存储时 cb/ca/mc 返回内置默认；
        rc 返回 [] = 上游 catalog 全量（以小浣熊线上为准）。"""
        stored = settings.get(f"{key}_models") or []
        if stored:
            return list(stored)
        if key == "cb":
            return list(CB_MODEL_CANDIDATES)
        if key == "ca":
            return list(CA_MODEL_CANDIDATES)
        if key == "rc":
            return []
        if key == "lo":
            return list(stored) or list(LO_DEFAULT_MODELS)
        return list(MC_DEFAULT_MODELS)

    def apply_models_live(key: str, sel: list):
        """把模型选择立即应用到已加载的核心（无需重启服务）。"""
        if key == "cb":
            conv = sys.modules.get("converter")
            if conv is not None:
                conv.CONFIG["exposed_models"] = list(sel)
        elif key == "mc":
            mc = sys.modules.get("monkeycode2openai")
            if mc is not None:
                mc.CONFIG["exposed_models"] = list(sel)
        elif key == "ca":
            ca = sys.modules.get("codearts2openai")
            if ca is not None:
                ca.CONFIG["exposed_models"] = list(sel)
        elif key == "rc":
            rc = sys.modules.get("raccoon2openai")
            if rc is not None:
                rc.CONFIG["exposed_models"] = list(sel)
        elif key == "lo":
            lo = sys.modules.get("loomy2openai")
            if lo is not None:
                lo.CONFIG["exposed_models"] = list(sel)

    def refresh_model_hints():
        cb = eff_models("cb")
        mc = eff_models("mc")
        ca = eff_models("ca")
        rc = eff_models("rc")
        lo = eff_models("lo")
        cb_models_hint.set("模型: " + (", ".join(_disp("cb", m) for m in cb[:4]) + (" …共%d个" % len(cb) if len(cb) > 4 else "") if cb else "全部"))
        mc_models_hint.set("模型: " + (", ".join(mc[:4]) + (" …共%d个" % len(mc) if len(mc) > 4 else "") if mc else "默认"))
        ca_models_hint.set("模型: " + (", ".join(_disp("ca", m) for m in ca) if ca else "默认"))
        rc_models_hint.set("模型: " + (", ".join(rc[:4]) + (" …共%d个" % len(rc) if len(rc) > 4 else "") if rc else "上游全量（catalog）"))
        lo_models_hint.set("模型: " + (", ".join(lo[:4]) + (" …共%d个" % len(lo) if len(lo) > 4 else "") if lo else "默认"))

    def _mc_snap() -> dict:
        """读额度缓存里的 mc 快照。无 IO，可在 Tk 线程安全调用。"""
        try:
            with _q_lock:
                return dict(_q_data["mc"]) if _q_data.get("mc") else {}
        except Exception:  # noqa: BLE001
            return {}

    def mc_usage_text() -> str:
        """今日用量。读后台缓存（原来是本线程发 HTTP，timeout=3 会卡界面）。"""
        d = _mc_snap().get("_usage") or {}
        if not d:
            return ""
        return (f"✓ 今日已用 {d.get('total', 0):,} tokens"
                f" · prompt {d.get('prompt', 0):,} / completion {d.get('completion', 0):,}"
                f" · {d.get('requests', 0)} 次请求")

    def refresh_mc_info():
        """mc_info 多行显示：第1行上游，第2行今日用量，第3行积分，第4行号池"""
        mc = sys.modules.get("monkeycode2openai")
        if mc is not None and mc.CONFIG.get("base_url"):
            line1 = (f"✓ 上游 {mc.CONFIG['base_url']}"
                     f" · key {(mc.CONFIG.get('api_key') or '')[:6]}…")
            fg = "#1a7f37"
        else:
            base = monkeycode_upstream_base()
            if base:
                line1 = f"✓ 上游已探测 {base}"
                fg = "#1a7f37"
            else:
                line1 = "✗ 未找到上游配置 —— 请打开 MonkeyCode 桌面端登录一次"
                fg = "#c0392b"
        u = mc_usage_text()
        w = mc_wallet_text()
        p = mc_pool_text()
        extra = "\n".join(x for x in (u, w, p) if x)
        mc_info.configure(text=line1 + (f"\n{extra}" if extra else ""), foreground=fg)

    def mc_pool_text() -> str:
        """号池状态行（仅服务运行时查 /health；关闭时显示配置数）"""
        if not POOL_FEATURE:
            return ""          # 号池已屏蔽，不显示任何号池信息
        try:
            ncfg = len(settings.get("mc_pool") or [])
            if not services["mc"].running:
                return f"号池关（已配 {ncfg} 个 key）" if not bool(mc_pool_on.get()) and ncfg else (
                    "" if not ncfg else f"号池开（{ncfg} 个 key，未运行）")
            pool = (_mc_snap().get("_health") or {}).get("pool") or {}
            if not pool.get("enabled"):
                return ""
            keys = pool.get("keys") or []
            ok = sum(1 for k in keys if not k.get("cooling") and not k.get("off"))
            return f"号池开·可用 {ok}/{len(keys)}"
        except Exception:
            return ""

    def _http_json(url, timeout=10, method="GET", data=None):
        """GET/POST 取 JSON；HTTPError 时也解析 body（网关 502 的 body 里有真错误信息）"""
        import urllib.request
        import urllib.error
        try:
            req = urllib.request.Request(url, data=data, method=method)
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return json.loads(r.read().decode("utf-8")), ""
        except urllib.error.HTTPError as e:
            try:
                d = json.loads(e.read().decode("utf-8"))
                return d, str(d.get("error") or d.get("detail") or f"HTTP {e.code}")
            except Exception:
                return {}, f"HTTP {e.code}"
        except Exception as e:  # noqa: BLE001
            return {}, str(e)

    def mc_wallet_text() -> str:
        """SaaS 钱包积分。读后台缓存（原来 timeout=10，会把界面卡住十秒）。"""
        with _q_lock:
            meta = dict(_q_meta.get("mc") or {})
            snap = dict(_q_data["mc"]) if _q_data.get("mc") else {}
        if not snap:
            err = str(meta.get("err") or "")
            if any(t in err for t in ("401", "会话", "过期")):
                return "● 积分不可用 · 会话已过期 —— 请打开 MonkeyCode 桌面端登录"
            return ""
        bal = float(snap.get("balance") or 0)
        dtb = int(snap.get("daily_token_balance") or 0)
        dtl = int(snap.get("daily_token_limit") or 0)
        return (f"✓ 积分 {bal / 1000:.2f}（{bal:,.0f}）"
                f" · 每日 token {dtb:,} / {dtl:,}")

    def mc_checkin():
        """签到：先查状态，未签则 POST 签到"""
        if not services["mc"].running:
            emit("[mc] 未运行，无法签到")
            return
        port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
        base = f"http://127.0.0.1:{port}"
        st, err = _http_json(base + "/v1/checkin", timeout=15)
        if err:
            emit(f"[mc] 签到状态查询失败：{err}")
            return
        if (st.get("data") or {}).get("checked_in"):
            emit("[mc] 今日已签到，无需重复")
            ui(refresh_mc_info)
            return
        res, err = _http_json(base + "/v1/checkin", timeout=120, method="POST", data=b"{}")
        if res.get("ok"):
            emit("[mc] 签到成功（+100 积分）")
        else:
            emit(f"[mc] 签到失败：{err or res.get('error')}")
        ui(refresh_mc_info)

    def _auto_checkin_quiet():
        """启动后自动签到：已签/失败都只记一条日志，不打扰"""
        import time as _t
        _t.sleep(3)
        if not services["mc"].running:
            return
        port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
        base = f"http://127.0.0.1:{port}"
        st, err = _http_json(base + "/v1/checkin", timeout=15)
        if err or (st.get("data") or {}).get("checked_in"):
            return
        res, _ = _http_json(base + "/v1/checkin", timeout=120, method="POST", data=b"{}")
        if res.get("ok"):
            emit("[mc] 自动签到成功（+100 积分）")
            ui(refresh_mc_info)

    def _mc_free_ids() -> set:
        """桌面端 config 里 monkeycode-basic/* 即本机有权用的免费基础模型（去前缀）"""
        try:
            from pathlib import Path as _P
            import os as _os
            home = _P.home()
            for base in (_os.environ.get("APPDATA"), home / "AppData" / "Roaming"):
                if not base:
                    continue
                p = _P(base) / "com.chaitin.baizhi.monkeycode" / "config.json"
                if not p.is_file():
                    continue
                data = json.loads(p.read_text(encoding="utf-8"))
                out = set()
                for m in (data.get("models") or []):
                    mid = m.get("model") or ""
                    if mid.startswith("monkeycode-basic/"):
                        out.add(mid.split("/", 1)[1])
                if out:
                    return out
        except Exception:
            pass
        return set(MC_MODEL_CANDIDATES)

    def _fetch_rc_catalog() -> list:
        """服务没跑时，直连小浣熊上游 catalog 拉显示名（description；以线上为准）；失败返回 []"""
        try:
            rc = import_raccoon()
            if hasattr(rc, "catalog_displays"):
                return list(rc.catalog_displays())
            cat = rc.fetch_catalog()
            out = []
            for c in (cat.get("categories") or []):
                for m in (c.get("models") or []):
                    n = ((m.get("description") or m.get("name") or m.get("model_name")) or "").strip()
                    if n and n not in out:
                        out.append(n)
            return out
        except Exception:
            return []

    def _core(key: str):
        """取已加载或静默加载的核心模块；失败返回 None（只读显示映射，无副作用）。"""
        modname = {"cb": "converter", "mc": "monkeycode2openai", "ca": "codearts2openai",
                   "rc": "raccoon2openai", "lo": "loomy2openai"}.get(key)
        if not modname:
            return None
        mod = sys.modules.get(modname)
        if mod is not None:
            return mod
        try:
            loader = {"cb": import_converter, "mc": import_monkeycode, "ca": import_codearts,
                      "rc": import_raccoon, "lo": import_loomy}[key]
            return loader(log=lambda *a: None)
        except Exception:
            return None

    def _disp(key: str, name: str) -> str:
        """内部名 -> 显示名（cb/ca 用软件模型表；rc 用 catalog；mc/cp 恒等）。失败回退原名。"""
        try:
            mod = _core(key)
            if mod is not None and hasattr(mod, "display_of"):
                return mod.display_of(name) or name
            if key == "rc" and mod is not None and hasattr(mod, "catalog_name_map"):
                inv = {v: k for k, v in mod.catalog_name_map().items()}
                return inv.get(name, name)
        except Exception:
            pass
        return name

    def _resolve(key: str, name: str) -> str:
        """显示名或内部名 -> 线上内部名。失败回退原名。"""
        try:
            mod = _core(key)
            if mod is not None and hasattr(mod, "resolve_model"):
                return mod.resolve_model(name) or name
            if key == "rc" and mod is not None and hasattr(mod, "catalog_name_map"):
                return mod.catalog_name_map().get(name, name)
        except Exception:
            pass
        return name

    def _latest_internals(key: str) -> list:
        """各通道最新线上内部名表（catalog/静态表/实时）；拿不到返回 []（调用方用上回兜底）。"""
        try:
            if key == "cb":
                return list(CB_MODEL_CANDIDATES)
            if key == "ca":
                return list(CA_MODEL_CANDIDATES)
            if key == "lo":
                return list(LO_MODEL_CANDIDATES)
            if key == "rc":
                mod = _core("rc")
                if mod is not None and hasattr(mod, "catalog_name_map"):
                    mp = mod.catalog_name_map()
                    if mp:
                        return list(mp.values())
                return []
            if key == "mc":
                if services.get("mc") and services["mc"].running:
                    return _fetch_live_models("mc")
                return []
        except Exception:
            pass
        return []

    def _validate_models():
        """启动时验证各通道暴露模型名：显示优先 catalog 显示名，内部仍用线上名；
        无最新则用上回存储名兜底（只验证显示，不改存储）。"""
        names = {"cb": "WorkBuddy", "mc": "MonkeyCode", "ca": "华为云", "rc": "小浣熊", "lo": "Loomy"}
        for key in ("cb", "mc", "ca", "rc", "lo"):
            try:
                stored = settings.get(f"{key}_models") or []
                latest = _latest_internals(key)
                if not latest:
                    emit(f"[models] {names[key]}：未取到最新列表，用上回名称兜底（{len(stored)}个）")
                    continue
                latest_disp = [_disp(key, m) for m in latest]
                if not stored:
                    emit(f"[models] {names[key]}：最新{len(latest)}个（默认全量）· 例：{', '.join(latest_disp[:3])}")
                    continue
                hit = sum(1 for s in stored if _resolve(key, s) in latest or s in latest)
                miss = [s for s in stored if _resolve(key, s) not in latest and s not in latest]
                extra = f" · 失效：{', '.join(miss)}" if miss else ""
                emit(f"[models] {names[key]}：最新{len(latest)}个，存储{len(stored)}个（命中{hit}/失效{len(miss)}）{extra}")
            except Exception as e:  # noqa: BLE001
                emit(f"[models] {names.get(key, key)} 验证失败：{e}")

    def _local_chat_base(key: str) -> str:
        """该通道的本地 OpenAI 兼容 chat base（测试 / 工具能力探测都打这里）。

        cb 用它自己的地址（默认 http://127.0.0.1:8787/v1）；
        其余走各服务的端口输入框，非法值回退默认端口。
        """
        ent_dflt = {"mc": (mc_port, "9000"), "ca": (ca_port, "9100"),
                    "rc": (rc_port, "9200"), "lo": (lo_port, "9400")}.get(key)
        if not ent_dflt:
            return cb_url.get().strip().rstrip("/")
        ent, dflt = ent_dflt
        s = ent.get().strip()
        return f"http://127.0.0.1:{s if s.isdigit() else dflt}/v1"

    def _fetch_live_models(key: str) -> list:
        """从运行中的服务拉全量模型 id（mc 带 ?all=1 跳过白名单）；失败返回 []"""
        try:
            import urllib.request
            if key == "mc":
                port = mc_port.get().strip() if mc_port.get().strip().isdigit() else "9000"
                url = f"http://127.0.0.1:{port}/v1/models?all=1"
            elif key == "rc":
                port = rc_port.get().strip() if rc_port.get().strip().isdigit() else "9200"
                url = f"http://127.0.0.1:{port}/v1/models"
            elif key == "lo":
                port = lo_port.get().strip() if lo_port.get().strip().isdigit() else "9400"
                url = f"http://127.0.0.1:{port}/v1/models"
            elif key == "ca":
                port = ca_port.get().strip() if ca_port.get().strip().isdigit() else "9100"
                url = f"http://127.0.0.1:{port}/v1/models"
            else:
                url = cb_url.get().rstrip("/") + "/models"
            with urllib.request.urlopen(url, timeout=8) as r:
                d = json.loads(r.read().decode("utf-8"))
            ids = [m.get("id") for m in (d.get("data") or []) if isinstance(m, dict) and m.get("id")]
            stored = settings.get(f"{key}_models") or []
            ids += [m for m in stored if m not in ids]
            return ids
        except Exception:
            return []

    def models_dialog(key: str):
        titles = {"cb": "CodeBuddy → OpenAI", "mc": "MonkeyCode → OpenAI", "ca": "CodeArts → OpenAI",
                  "rc": "Raccoon → OpenAI", "lo": "Loomy → OpenAI"}

        def compute_cands() -> list:
            """取候选模型名；点“刷新模型”时会重新调用一次（线上实时为准）。"""
            if key == "rc":
                # rc 取数顺序：上游 catalog 为准 → 线上服务兜底 → 内置名单最后兜底
                live = _fetch_live_models(key) if services.get(key) and services[key].running else []
                if (cat := _fetch_rc_catalog()):
                    cands = list(cat)
                elif live:
                    cands = list(live)
                else:
                    cands = list(RACOON_MODEL_CANDIDATES)
            elif key == "mc":
                live = _fetch_live_models(key) if services.get(key) and services[key].running else []
                if live:
                    free = _mc_free_ids()
                    cands = sorted([m for m in live if m in free]) + sorted([m for m in live if m not in free])
                else:
                    cands = list(MC_MODEL_CANDIDATES)
            elif key in ("cb", "ca"):
                # 显示优先软件模型表显示名；无映射则用线上名（与 _validate_models 一致）
                base = {"cb": CB_MODEL_CANDIDATES, "ca": CA_MODEL_CANDIDATES}[key]
                cands = [_disp(key, m) for m in base]
            else:
                cands = {"mc": MC_MODEL_CANDIDATES, "cb": CB_MODEL_CANDIDATES,
                         "rc": RACOON_MODEL_CANDIDATES, "lo": LO_MODEL_CANDIDATES}.get(key, CA_MODEL_CANDIDATES)
            ver = settings.get(f"{key}_verified") or {}
            if "dead" in ver:
                dead_set = set(ver.get("dead") or [])
                cands = [m for m in cands if _resolve(key, m) not in dead_set]
            return list(cands)

        win = tk.Toplevel(root)
        win.title("选择暴露的模型 · " + titles.get(key, key))
        win.transient(root)
        win.grab_set()
        frm = ttk.Frame(win, padding=14)
        frm.pack(fill="both", expand=True)
        top = ttk.Frame(frm)
        top.pack(fill="x")
        ttk.Label(top, text="勾选要在 /v1/models 中暴露的模型：",
                  justify="left").pack(anchor="w")
        # 能力标注（仅 MonkeyCode 有逐模型元数据）：标出不支持图片输入的模型
        hint = ttk.Label(top, text="", foreground="#6b7280", justify="left")

        listfrm = ttk.Frame(frm)
        listfrm.pack(fill="both", expand=True, pady=(8, 0))
        state: dict = {"cands": [], "vars": {}}

        def render(preserve: bool = False):
            """按当前候选重建复选框网格；preserve=True 时保留已勾选状态。"""
            for w in listfrm.winfo_children():
                w.destroy()
            prev = {m: v.get() for m, v in state["vars"].items()} if preserve else {}
            cands = compute_cands()
            state["cands"] = cands
            caps = mc_model_caps() if key == "mc" else {}
            tools_map = (settings.get(f"{key}_verified") or {}).get("tools")
            if not isinstance(tools_map, dict):
                tools_map = {}

            def caps_of(m: str) -> dict:
                if not caps:
                    return {}
                full = m if "/" in m else ("monkeycode-basic/" + m)
                return caps.get(m) or caps.get(full) or {}

            eff = eff_models(key)
            all_on = (not eff and key == "rc")  # rc 空 = 上游全量，默认全勾
            eff_disp = {_disp(key, m) for m in eff} | set(eff)
            eff_int = {_resolve(key, m) for m in eff} | set(eff)
            ncol = 3 if len(cands) > 20 else 2
            vars_map = {}
            n_noimg = n_notool = 0
            for i, m in enumerate(cands):
                if preserve and m in prev:
                    val = prev[m]
                else:
                    val = (m in eff_disp) or (_resolve(key, m) in eff_int) if not all_on else True
                v = tk.BooleanVar(value=val)
                vars_map[m] = v
                lacks = []
                if caps_of(m).get("images") is False:
                    lacks.append("无图像")
                    n_noimg += 1
                if tools_map.get(m) is False:
                    lacks.append("无工具")
                    n_notool += 1
                label = f"{m}（{'·'.join(lacks)}）" if lacks else m
                ttk.Checkbutton(listfrm, text=label, variable=v).grid(
                    row=i // ncol, column=i % ncol, sticky="w", padx=8, pady=3)
            state["vars"] = vars_map
            bits = []
            if n_noimg:
                bits.append(f"「无图像」＝不支持图片输入（{n_noimg} 个）")
            if n_notool:
                bits.append(f"「无工具」＝工具调用探测未通过（{n_notool} 个）")
            elif tools_map:
                n_ok = sum(1 for v in tools_map.values() if v is True)
                n_unk = sum(1 for v in tools_map.values() if v is None)
                t = f"工具调用：{n_ok} 个已探测通过"
                if n_unk:
                    t += f"，{n_unk} 个未测出"
                bits.append(t)
            else:
                bits.append("工具调用能力尚未探测：勾选模型后点「探测能力/速度」")
            if bits:
                hint.configure(text="；".join(bits) + "。")
                hint.pack(anchor="w", pady=(2, 0))
            else:
                hint.pack_forget()

        render()

        crow = ttk.Frame(frm)
        crow.pack(fill="x", pady=(10, 0))
        ttk.Label(crow, text="自定义(逗号分隔):").pack(side="left")
        custom = ttk.Entry(crow, width=36)
        custom.pack(side="left", padx=(6, 0))

        def save():
            cands, vars_map = state["cands"], state["vars"]
            sel = [m for m in cands if vars_map.get(m) and vars_map[m].get()]
            sel += [x.strip() for x in custom.get().split(",") if x.strip()]
            sel = list(dict.fromkeys(sel))
            if key == "rc" and set(sel) >= set(cands):
                sel = []  # rc 全选 = 上游全量，不存名单（以上游 catalog 为准）
            settings[f"{key}_models"] = sel
            save_settings(settings)
            apply_models_live(key, sel)
            refresh_model_hints()
            emit(f"[{key}] 暴露模型已更新: {', '.join(sel) if sel else ('上游全量' if key == 'rc' else '默认')}")
            win.destroy()

        def do_refresh():
            """只重新拉取候选模型列表（不探测能力——那个慢，走单独按钮）。"""
            render(preserve=True)
            n = len(state["cands"])
            if n:
                emit(f"[{key}] 模型列表已刷新（{n}个）")
            else:
                emit(f"[{key}] 模型列表刷新失败：未取到候选（服务未运行？）")

        def do_probe_tools():
            """探测**当前勾选**模型的能力：工具调用 + 首字延迟/速度（逐个请求，较慢）。"""
            checked = [m for m in state["cands"]
                       if state["vars"].get(m) and state["vars"][m].get()]
            if not checked:
                emit(f"[{key}] 请先勾选要探测的模型")
                return
            if not (services.get(key) and services[key].running):
                emit(f"[{key}] 服务未运行，无法探测")
                return
            base = _local_chat_base(key)
            if btns_probe is not None:
                btns_probe.configure(state="disabled")

            def _bg():
                try:
                    emit(f"[{key}] 开始探测（{len(checked)} 个勾选模型：工具能力 + 速度）…")
                    tmap, smap = {}, {}
                    for m in checked:
                        tmap[m] = probe_model_tools(base, m)
                        smap[m] = probe_model_speed(base, m)
                        tag = {True: "支持", False: "不支持", None: "未测出"}[tmap[m]]
                        emit(f"[{key}] {m}  工具={tag}  {_fmt_speed(smap[m])}")
                    rec = dict(settings.get(f"{key}_verified") or {})
                    old_t = rec.get("tools") if isinstance(rec.get("tools"), dict) else {}
                    old_t.update(tmap)      # 合并：未探测模型保留上次结果
                    old_s = rec.get("speed") if isinstance(rec.get("speed"), dict) else {}
                    old_s.update(smap)
                    rec["tools"], rec["tools_ts"] = old_t, time.time()
                    rec["speed"], rec["speed_ts"] = old_s, time.time()
                    settings[f"{key}_verified"] = rec
                    try:
                        save_settings(settings)
                    except Exception:
                        pass
                    n_tool = sum(1 for v in tmap.values() if v is True)
                    bad = [k for k, v in tmap.items() if v is False]
                    unk = [k for k, v in tmap.items() if v is None]
                    # 速度汇总：挑最快的
                    raced = [(v.get("tps"), k) for k, v in smap.items()
                             if isinstance(v.get("tps"), (int, float))]
                    fastest = f" · 最快 {max(raced)[1]} 约 {max(raced)[0]:.1f} t/s" if raced else ""
                    emit(f"[{key}] 探测完成：工具 {n_tool}/{len(tmap)} 支持"
                         + (f" · 不支持：{', '.join(bad)}" if bad else "")
                         + (f" · 未测出：{', '.join(unk)}" if unk else "")
                         + fastest)
                except Exception as e:  # noqa: BLE001
                    emit(f"[{key}] 探测失败：{e}")
                finally:
                    if btns_probe is not None:
                        ui(lambda: btns_probe.configure(state="normal"))
                    ui(lambda: render(preserve=True))

            threading.Thread(target=_bg, daemon=True).start()

        btns = ttk.Frame(frm)
        btns.pack(fill="x", pady=(12, 0))
        ttk.Button(btns, text="保存", command=save).pack(side="right")
        ttk.Button(btns, text="取消", command=win.destroy).pack(side="left", padx=4)
        ttk.Button(btns, text="刷新模型", command=do_refresh).pack(side="left")
        btns_probe = ttk.Button(btns, text="探测能力/速度", command=do_probe_tools)
        btns_probe.pack(side="left", padx=(4, 0))

    def pool_dialog(key: str):
        """通用号池管理对话框（key: 'mc' | 'ca'）。

        两个通道共用同一套调度引擎（buddyzpool），所以 GUI 也共用一套：
          · 列表：状态 / 标签 / 权重 / 优先级 / 在途 / 成功·失败 / 连续失败 / 冷却 / 上次错误
          · 设置：策略、冷却基数、连续失败阈值、最大重试、失效复检、单条并发、会话粘性
          · 按钮：抓取本机 / 添加(mc) / 启用停用 / 删除 / 测试全部 / 清空冷却 / 重置统计

        策略说明（参考 LiteLLM Router 的生产实践）：
          round_robin   顺序轮转——最稳、零开销，默认
          least_busy    在途 + 近一分钟请求数最少——分流最均
          weighted      按权重加权随机——给快号更多流量
          least_latency 观测延迟最低（带缓冲带，避免打满最快那条）

        注意：号池当前被屏蔽（POOL_FEATURE=False），GUI 里没有入口。
        下面这道早退是第二道防线 —— 万一被程序化调用也不会真把池开起来。
        """
        if not POOL_FEATURE:
            emit("[pool] 号池功能已屏蔽（POOL_FEATURE=False），不提供管理界面")
            return
        is_mc = (key == "mc")
        names = {"mc": "MonkeyCode", "ca": "CodeArts（华为云）"}
        enable_var = mc_pool_on if is_mc else ca_pool_on
        conf_key = ("mc_pool_cfg" if is_mc else "ca_pool_cfg")
        mod = _core(key)

        def _mod():
            return sys.modules.get("monkeycode2openai" if is_mc else "codearts2openai") or mod

        def _sync_mc():
            """mc 的池条目存在 settings.json，改完推给核心 + 让引擎复位。"""
            m = sys.modules.get("monkeycode2openai")
            if m is None:
                return
            m.CONFIG["pool_keys"] = [dict(k) for k in (settings.get("mc_pool") or [])]
            try:
                eng = m._pool_engine()
                if eng is not None:
                    eng.invalidate()
            except Exception:  # noqa: BLE001
                pass

        def entries() -> list:
            if is_mc:
                return [dict(e) for e in (settings.get("mc_pool") or []) if isinstance(e, dict)]
            m = _mod()
            try:
                return m.pool_list() if m is not None else []
            except Exception:  # noqa: BLE001
                return []

        def snapshot() -> dict:
            m = _mod()
            try:
                return m._pool_state() if m is not None else {}
            except Exception:  # noqa: BLE001
                return {}

        def cfg_now() -> dict:
            m = _mod()
            try:
                if m is not None and hasattr(m, "pool_config"):
                    return m.pool_config()
            except Exception:  # noqa: BLE001
                pass
            return dict(settings.get(conf_key) or {})

        # ---------------- 窗口 ----------------
        win = tk.Toplevel(root)
        win.title(f"{names[key]} 号池管理")
        win.transient(root)
        win.grab_set()
        frm = ttk.Frame(win, padding=12)
        frm.pack(fill="both", expand=True)

        ttk.Label(frm, justify="left", wraplength=int(760 * scale),
                  text=("多凭据调度：按策略挑一条用，失败自动换下一条；"
                        "连续失败会熔断冷却并指数退避，冷却到期自动回到候选；"
                        "凭据失效（401/403）转入「失效」并按复检间隔自动重试恢复。")
                  ).pack(anchor="w")

        head = ttk.Label(frm, text="", foreground="#0a58ca")
        head.pack(anchor="w", pady=(4, 0))

        lst = tk.Listbox(frm, width=104, height=9, font=F_MONO)
        lst.pack(fill="x", pady=(6, 4))

        # ---------------- 设置区 ----------------
        cf = ttk.LabelFrame(frm, text=" 调度设置 ", padding=6)
        cf.pack(fill="x", pady=(4, 0))
        r1 = ttk.Frame(cf)
        r1.pack(fill="x")
        ttk.Label(r1, text="策略").pack(side="left")
        strat = tk.StringVar(value=cfg_now().get("strategy", "round_robin"))
        ttk.Combobox(r1, textvariable=strat, width=14, state="readonly",
                     values=["round_robin", "least_busy", "weighted",
                             "least_latency"]).pack(side="left", padx=(4, 10))
        ttk.Label(r1, text="冷却基数(秒)").pack(side="left")
        e_cool = ttk.Entry(r1, width=6)
        e_cool.insert(0, str(int(cfg_now().get("cooldown_base", 30))))
        e_cool.pack(side="left", padx=(4, 10))
        ttk.Label(r1, text="连续失败阈值").pack(side="left")
        e_fails = ttk.Entry(r1, width=4)
        e_fails.insert(0, str(int(cfg_now().get("allowed_fails", 3))))
        e_fails.pack(side="left", padx=(4, 10))
        ttk.Label(r1, text="最大重试").pack(side="left")
        e_retry = ttk.Entry(r1, width=4)
        e_retry.insert(0, str(int(cfg_now().get("max_retries", 2))))
        e_retry.pack(side="left", padx=(4, 10))

        r2 = ttk.Frame(cf)
        r2.pack(fill="x", pady=(4, 0))
        ttk.Label(r2, text="失效复检(分钟)").pack(side="left")
        e_recheck = ttk.Entry(r2, width=5)
        e_recheck.insert(0, str(int(float(cfg_now().get("off_recheck", 1800)) // 60)))
        e_recheck.pack(side="left", padx=(4, 10))
        ttk.Label(r2, text="单条并发上限(0=不限)").pack(side="left")
        e_infl = ttk.Entry(r2, width=4)
        e_infl.insert(0, str(int(cfg_now().get("max_inflight", 0))))
        e_infl.pack(side="left", padx=(4, 10))
        aff_var = tk.BooleanVar(value=bool(cfg_now().get("affinity", False)))
        ttk.Checkbutton(r2, text="会话粘性（同一会话固定同一条，利于上游缓存）",
                        variable=aff_var).pack(side="left", padx=(0, 10))
        ttk.Button(r2, text="保存设置", command=lambda: save_cfg()).pack(side="left")

        hint = ttk.Label(frm, text="", foreground="#6b7280", justify="left",
                         wraplength=int(760 * scale))
        hint.pack(anchor="w", pady=(4, 0))

        def _fmt(s: dict) -> str:
            state = s.get("state") or "ok"
            tag = {"ok": "OK  ", "cooling": "COOL", "off": "OFF "}.get(state, "?   ")
            if not s.get("enabled"):
                tag = "DIS "
            cool = f"{s.get('cool_remain', 0):.0f}s" if s.get("cool_remain") else "-"
            err = (s.get("last_error") or "")[:26]
            extra = s.get("extra") or {}
            tag2 = ""
            if isinstance(extra, dict) and extra.get("station"):
                tag2 = "国际" if extra["station"] == "international" else "国内"
            elif "station" in s:
                tag2 = "国际" if s.get("station") == "international" else "国内"
            return (f"[{tag}] {s.get('label', '')[:26]:26} {tag2} "
                    f"w{s.get('weight', 1)}/p{s.get('priority', 0)} "
                    f"in{s.get('inflight', 0)} "
                    f"✓{s.get('ok', 0):<4} ✗{s.get('fail', 0):<4} "
                    f"连{s.get('consec', 0)} 冷{cool:>6} {err}")

        def reload_list():
            lst.delete(0, "end")
            st = snapshot()
            for s in (st.get("keys") or []):
                lst.insert("end", _fmt(s))
            sm = st.get("summary") or {}
            head.configure(
                text=(f"共 {sm.get('total', len(entries()))} 条 · "
                      f"可用 {sm.get('ok', '?')} · 冷却 {sm.get('cooling', '?')} · "
                      f"失效 {sm.get('off', '?')} · 禁用 {sm.get('disabled', '?')} · "
                      f"策略 {st.get('strategy') or cfg_now().get('strategy', '-')} · "
                      f"号池{'已开' if enable_var.get() else '关闭'}"))
            hint.configure(text=("提示：本机登录（桌面端/VS Code）与号池里的会话共用一把 "
                                 "refresh_token，谁先用谁轮转，另一方那份会失效需重登。"
                                 "建议池里放「其它账号」的会话，本机那条只当打底。"))

        reload_list()

        def save_cfg():
            def _int(ent, dflt):
                try:
                    return int(float(ent.get().strip()))
                except (TypeError, ValueError):
                    return dflt
            cfg = {
                "strategy": strat.get().strip() or "round_robin",
                "cooldown_base": max(1, _int(e_cool, 30)),
                "allowed_fails": max(1, _int(e_fails, 3)),
                "max_retries": max(0, _int(e_retry, 2)),
                "off_recheck": max(10, _int(e_recheck, 30) * 60),
                "max_inflight": max(0, _int(e_infl, 0)),
                "affinity": bool(aff_var.get()),
            }
            m = _mod()
            if m is not None and hasattr(m, "pool_set_config"):
                try:
                    m.pool_set_config(**cfg)
                except Exception as e:  # noqa: BLE001
                    emit(f"[{key}-pool] 设置失败：{e}")
                    return
            settings[conf_key] = cfg          # 落盘，供下次启动
            if is_mc:
                m2 = sys.modules.get("monkeycode2openai")
                if m2 is not None:
                    m2.CONFIG["pool_cfg"] = dict(cfg)
            save_settings(settings)
            emit(f"[{key}-pool] 调度设置已保存：{cfg['strategy']} · "
                 f"冷却基数 {cfg['cooldown_base']}s · 失败阈值 {cfg['allowed_fails']} · "
                 f"重试 {cfg['max_retries']} · 复检 {cfg['off_recheck'] // 60}min")
            reload_list()

        # ---------------- 操作 ----------------
        def toggle_sel():
            sel = lst.curselection()
            if not sel:
                return
            i = sel[0]
            if is_mc:
                pool = settings.get("mc_pool") or []
                if 0 <= i < len(pool):
                    pool[i]["enabled"] = not pool[i].get("enabled", True)
                    _persist()
                    _sync_mc()
            else:
                m = _mod()
                if m is not None:
                    # pool_toggle 内部已 _pool_invalidate()（清冷却/粘性），
                    # 别再调 pool_clear_cooldowns —— 那会把别的失效条目也一起复活
                    m.pool_toggle(i)
            reload_list()

        def del_sel():
            sel = lst.curselection()
            if not sel:
                return
            i = sel[0]
            if is_mc:
                pool = settings.get("mc_pool") or []
                if 0 <= i < len(pool):
                    pool.pop(i)
                    _persist()
                    _sync_mc()
            else:
                m = _mod()
                if m is not None and m.pool_remove(i):
                    pass
            reload_list()

        def clear_cool():
            m = _mod()
            if m is not None and hasattr(m, "pool_clear_cooldowns"):
                m.pool_clear_cooldowns()
            else:
                try:
                    eng = m._pool_engine() if m is not None else None
                    if eng is not None:
                        eng.clear_cooldowns()
                except Exception:  # noqa: BLE001
                    pass
            emit(f"[{key}-pool] 已清空冷却/失效标记")
            reload_list()

        def reset_stats():
            m = _mod()
            try:
                if m is not None:
                    m.pool_reset_stats()
            except Exception:  # noqa: BLE001
                pass
            emit(f"[{key}-pool] 已重置统计")
            reload_list()

        def test_all():
            """逐条实测：复用主面板同款批量测试（含确认、按号池规则处置）。"""
            n_before = len(entries())
            got, total = _pool_test_all(key)
            if total == 0 and n_before:
                emit(f"[{key}-pool] 未能批量测试（未勾选号池或核心未就绪）")
            reload_list()

        def harvest():
            """从本机登录来源收集会话进池（mc 填到输入框，ca 直接入池）。"""
            if is_mc:
                grab_local()
                return
            m = _mod()
            if m is None:
                emit("[ca-pool] 核心未加载")
                return
            try:
                res = m.pool_harvest()
            except Exception as e:  # noqa: BLE001
                emit(f"[ca-pool] 抓取失败：{e}")
                return
            if enable_var.get():
                m.CONFIG["pool_enabled"] = True
            reload_list()
            got = res.get("added") or []
            skip = res.get("skipped") or []
            if got:
                emit(f"[ca-pool] 已收录 {len(got)} 条：{'、'.join(got)}")
            if skip:
                emit(f"[ca-pool] 已在池中：{'、'.join(skip)}")
            if not got and not skip:
                emit("[ca-pool] 本机没找到可用登录（先登录一次桌面端/VS Code 插件）")

        def add_key():
            base, k, lab = e_base.get().strip(), e_key.get().strip(), e_label.get().strip()
            if not base or not k:
                emit("[mc-pool] base_url 和 api_key 都要填")
                return
            pool = settings.get("mc_pool") or []
            if any(x.get("api_key") == k for x in pool):
                emit("[mc-pool] 该 key 已存在")
                return
            pool.append({"base_url": base, "api_key": k, "enabled": True,
                         "label": lab or f"号{len(pool) + 1}",
                         "weight": 1, "priority": 0})
            settings["mc_pool"] = pool
            _persist()
            _sync_mc()
            e_label.delete(0, "end")
            e_key.delete(0, "end")
            emit(f"[mc-pool] 已添加（共 {len(pool)} 条）")
            reload_list()

        # mc 才需要手工录入行
        if is_mc:
            ir = ttk.Frame(frm)
            ir.pack(fill="x", pady=(6, 0))
            ttk.Label(ir, text="备注名").pack(side="left")
            e_label = ttk.Entry(ir, width=14)
            e_label.pack(side="left", padx=(4, 8))
            ttk.Label(ir, text="base_url").pack(side="left")
            e_base = ttk.Entry(ir, width=40)
            e_base.insert(0, "https://ai-models.app.baizhi.cloud/api/openai/v1")
            e_base.pack(side="left", padx=(4, 8))
            ttk.Label(ir, text="api_key").pack(side="left")
            e_key = ttk.Entry(ir, width=22)
            e_key.pack(side="left", padx=(4, 0))

        btns = ttk.Frame(frm)
        btns.pack(fill="x", pady=(10, 0))
        ttk.Button(btns, text="抓取本机", command=harvest).pack(side="left", padx=3)
        if is_mc:
            ttk.Button(btns, text="添加", command=add_key).pack(side="left", padx=3)
        ttk.Button(btns, text="启用/停用", command=toggle_sel).pack(side="left", padx=3)
        ttk.Button(btns, text="删除选中", command=del_sel).pack(side="left", padx=3)
        ttk.Button(btns, text="测试全部", command=test_all).pack(side="left", padx=3)
        ttk.Button(btns, text="清空冷却", command=clear_cool).pack(side="left", padx=3)
        ttk.Button(btns, text="重置统计", command=reset_stats).pack(side="left", padx=3)
        ttk.Button(btns, text="刷新", command=reload_list).pack(side="left", padx=3)
        ttk.Button(btns, text="关闭", command=win.destroy).pack(side="right", padx=3)

        # mc 的 grab_local 定义在 pool_dialog 之后的地方（历史原因），这里按需补一个
        def grab_local():
            got = None
            try:
                from pathlib import Path as _P
                kf = (_P.home() / "AppData" / "Roaming" /
                      "com.chaitin.baizhi.monkeycode" / "monkeycode-ohmyagent-key.json")
                if kf.is_file():
                    j = json.loads(kf.read_text(encoding="utf-8"))
                    base = (j.get("base_url") or "").rstrip("/")
                    keyv = j.get("api_key") or ""
                    if base and keyv:
                        got = (base, keyv, "国际版" if "monkeycode-ai.net" in base else "国内版")
                if got is None:
                    p = (_P.home() / "AppData" / "Roaming" /
                         "com.chaitin.baizhi.monkeycode" / "config.json")
                    data = json.loads(p.read_text(encoding="utf-8"))
                    cand = [(mm.get("base_url", "").rstrip("/"), mm.get("api_key", ""))
                            for mm in (data.get("models") or [])
                            if mm.get("api_key") and mm.get("base_url")]
                    if cand:
                        base, keyv = cand[0]
                        for b, kk in cand:
                            if "openai" in b:
                                base, keyv = b, kk
                                break
                        got = (base, keyv, "")
            except Exception as e:  # noqa: BLE001
                emit(f"[mc-pool] 抓取失败：{e}")
                return
            if not got:
                emit("[mc-pool] 本机没找到 key（桌面端未登录？）")
                return
            base, keyv, ver = got
            e_base.delete(0, "end")
            e_base.insert(0, base)
            e_key.delete(0, "end")
            e_key.insert(0, keyv)
            emit(f"[mc-pool] 已抓取本机 key（{keyv[:6]}… {ver}），填备注名点「添加」")
    def ensure_ready() -> bool:
        miss = missing_deps()
        if miss:
            emit(f"[deps] 缺少依赖：{' '.join(miss)}，自动安装…")
            if not install_deps(emit):
                return False
        return True

    def start_cb():
        svc = services["cb"]
        if svc.running:
            emit("[cb] 已在运行")
            return
        if not ensure_ready():
            return
        try:
            port = int(cb_port.get())
        except ValueError:
            emit("[cb] 端口无效"); return
        host = _host()
        if not port_free(host, port):
            if reclaim_stale_port(host, port, emit) and port_free(host, port):
                emit(f"[cb] 已关闭残留进程并释放端口 {port}，继续启动")
            else:
                _ui_status("cb", "error", f"端口 {port} 被占用")
                return
        emit(f"[cb] 启动中 … http://{host}:{port}")
        try:
            conv = import_converter(emit)
            conv.CONFIG["api_key"] = cb_key.get().strip()
            conv.CONFIG["desensitize"] = bool(cb_desens.get())
            conv.CONFIG["log_path"] = None   # 已移除「请求日志(文件)」，不再写盘
            # 使用版本：自动 / 国内 / 国际 —— 决定读哪一个 auth 文件。
            # 两版可同时登录，各占一个文件，因此互不覆盖。
            _st = None if cb_station.get() == "auto" else cb_station.get()
            conv.CONFIG["station"] = _st
            af = conv.find_auth_file()
            conv.CONFIG["cred"] = conv.CredentialManager(af) if af else None
            conv.CONFIG["exposed_models"] = eff_models("cb")
            if af is None:
                _want = WB_STATION_LABEL.get(_st, "（自动）")
                emit(f"[cb] ⚠ 未找到{_want}的登录凭据 —— 请先在对应版本桌面端登录"
                     "（国内 WorkBuddy / 国际 WorkBuddyAI）；服务可启动但请求会 503")
            else:
                try:
                    _sum = conv.CONFIG["cred"].summary()
                    emit(f"[cb] 使用版本={WB_STATION_LABEL.get(_sum.get('station'), '自动')}"
                         f" · 账号={_sum.get('nickname')} · {_sum.get('domain')}"
                         f" → {_sum.get('backend')}")
                except Exception:  # noqa: BLE001
                    pass
            svc.start(conv.app, host, port)
            _persist()
            ui(refresh_cb_credits)
        except Exception as e:  # noqa: BLE001
            emit(f"[cb] 启动失败：{type(e).__name__}: {e}")

    def start_mc():
        svc = services["mc"]
        if svc.running:
            emit("[mc] 已在运行")
            return
        if not ensure_ready():
            return
        try:
            port = int(mc_port.get())
        except ValueError:
            emit("[mc] 端口无效"); return
        host = _host()
        if not port_free(host, port):
            if reclaim_stale_port(host, port, emit) and port_free(host, port):
                emit(f"[mc] 已关闭残留进程并释放端口 {port}，继续启动")
            else:
                _ui_status("mc", "error", f"端口 {port} 被占用")
                return
        emit(f"[mc] 启动中 … http://{host}:{port}")
        try:
            mc = import_monkeycode(emit)
            mc.CONFIG["local_api_key"] = mc_key.get().strip()
            mc.CONFIG["exposed_models"] = eff_models("mc")
            mc.CONFIG["log_path"] = str(logs_dir() / "monkeycode2openai.log")
            # 使用版本：自动 / 国内 / 国际。选 cn/intl 时套用 mc_accounts.json 里的
            # 站点快照（桌面端两版共用一份配置，靠快照才能同时用两版账号）。
            mc.apply_station(None if mc_station.get() == "auto" else mc_station.get(), emit)
            mc.CONFIG["pool_enabled"] = bool(mc_pool_on.get())
            mc.CONFIG["pool_keys"] = [dict(k) for k in (settings.get("mc_pool") or [])]
            mc.CONFIG["pool_cfg"] = dict(settings.get("mc_pool_cfg") or {})
            if bool(mc_pool_on.get()):
                try:
                    n = len(mc._pool_engine().snapshot()) if mc._pool_engine() else 0
                except Exception:
                    n = len(mc.CONFIG["pool_keys"]) + 1
                emit(f"[mc-pool] 号池已开启（{n} 条候选 · "
                     f"策略 {(mc.CONFIG['pool_cfg'] or {}).get('strategy', 'round_robin')}）")
            if mc.CONFIG["base_url"] and mc.CONFIG["api_key"]:
                ui(refresh_mc_info)
            else:
                emit("[mc] ⚠ 未找到上游配置（config.json 中无 models[0].api_key），服务可启动但请求会失败")
            svc.start(mc.app, host, port)
            _persist()
            ui(refresh_mc_info)
            # 启动后顺手自动签到（已签则跳过，静默失败不打扰）
            threading.Thread(target=_auto_checkin_quiet, daemon=True).start()
        except Exception as e:  # noqa: BLE001
            emit(f"[mc] 启动失败：{type(e).__name__}: {e}")

    def start_ca():
        svc = services["ca"]
        if svc.running:
            emit("[ca] 已在运行")
            return
        if not ensure_ready():
            return
        try:
            port = int(ca_port.get())
        except ValueError:
            emit("[ca] 端口无效"); return
        host = _host()
