    # ---------------- 号池：批量测试（勾了号池时，主面板「测试」走这里） ----------------
    def _ensure_pool_ready(key: str):
        """把 settings 里的号池配置推给核心，返回可用的核心模块（失败 None）。

        顺带让「测试」不必等服务先启动：探测走的是模块自己的凭据/上游地址。
        """
        mod = _core(key)
        if mod is None:
            return None
        try:
            if key == "mc":
                # mc 的本机条目来自 auto_configure（读桌面端 config.json）
                if not (mod.CONFIG.get("base_url") and mod.CONFIG.get("api_key")):
                    mod.auto_configure(lambda *_a: None)
                mod.CONFIG["pool_keys"] = [dict(k) for k in (settings.get("mc_pool") or [])]
                mod.CONFIG["pool_cfg"] = dict(settings.get("mc_pool_cfg") or {})
            else:
                cfg = dict(settings.get("ca_pool_cfg") or {})
                if cfg and hasattr(mod, "pool_set_config"):
                    mod.pool_set_config(**cfg)
        except Exception as e:  # noqa: BLE001
            emit(f"[{key}-pool] 准备池配置失败：{e}")
        return mod

    def _pool_test_all(key: str) -> tuple:
        """号池已勾选时：逐个实测**全部**号，不通过的按号池规则处置。

        返回 (通过数, 总数)；未勾号池 / 池为空 / 不支持 → (None, 0)。

        处置由引擎统一执行（`manual=True` 表示显式探测，不等连续失败阈值）：
          401/403 → 停用（按复检间隔自动恢复）
          429     → 冷却 cooldown_base×k_429
          5xx     → 冷却 cooldown_base×k_5xx
          网络等  → 冷却 cooldown_base×k_net
        连续多次冷却按倍率指数退避，上限 cooldown_max。
        """
        on = mc_pool_on if key == "mc" else ca_pool_on
        if not on.get():
            return None, 0
        mod = _ensure_pool_ready(key)
        if mod is None or not (hasattr(mod, "pool_probe") and hasattr(mod, "pool_targets")):
            emit(f"[{key}-pool] 核心未加载或不支持探测")
            return None, 0
        try:
            # 必须用模块给的目标表：与 pool_probe(idx) 的索引严格对齐
            targets = list(mod.pool_targets() or [])
        except Exception as e:  # noqa: BLE001
            emit(f"[{key}-pool] 取号池条目失败：{e}")
            return None, 0
        if not targets:
            emit(f"[{key}-pool] 已勾选号池，但池里没有条目（先「抓取本机」或添加）")
            return None, 0

        if key != "mc" and not messagebox.askyesno(
                "确认测试号池",
                f"将逐个实测 {len(targets)} 条会话（真实调用续期接口）。\n"
                "每条会轮转自己的 refresh_token（网关自动回写新令牌）。\n\n"
                "注意：若某条会话与桌面端 / VS Code 插件共用，\n"
                "插件手里那一份会失效、需要重新登录。\n\n继续？"):
            emit(f"[{key}-pool] 已取消批量测试")
            return None, 0

        emit(f"[{key}-pool] 开始逐条实测（共 {len(targets)} 条）…")
        passed = 0
        for i, e in enumerate(targets):
            label = e.get("label") or f"#{i + 1}"
            extra = "" if e.get("enabled", True) else "（已停用，此次一并探活）"
            try:
                good, note = mod.pool_probe(i)
            except Exception as ex:  # noqa: BLE001
                good, note = False, f"{type(ex).__name__}: {ex}"
            passed += 1 if good else 0
            emit(f"[{key}-pool] {label}{extra} → "
                 f"{'✓ 可用' if good else '✗ 不可用'}（{note}）")
        emit(f"[{key}-pool] 批量测试完成：{passed}/{len(targets)} 通过"
             + ("（不通过的已按号池规则冷却/停用）" if passed < len(targets) else ""))
        return passed, len(targets)

