    def ca_auth():
        """生成 OAuth 授权 URL：先尝试自动拉起浏览器，失败则复制到剪贴板兜底"""
        import urllib.request
        import webbrowser
        # 取服务端口（运行中优先用实际端口，否则用输入框）
        port = None
        if services["ca"].running:
            try:
                port = ca_port.get().strip() if ca_port.get().strip().isdigit() else "9100"
                with urllib.request.urlopen(f"http://127.0.0.1:{port}/v1/auth/url", timeout=8) as r:
                    d = json.loads(r.read().decode("utf-8"))
                url = (d.get("data") or {}).get("url", "")
                if url:
                    try:
                        if webbrowser.open(url, new=2):
                            emit("[ca] 已拉起浏览器：在其中登录授权。"
                                 "授权后网关会**后台轮询换票**（最长 3 分钟，与官方插件同语义），"
                                 "完成后状态栏会显示“授权成功”，再点“测试”验证")
                            return
                    except Exception:
                        pass
                    root.clipboard_clear()
                    root.clipboard_append(url)
                    emit("[ca] 浏览器拉起失败，授权 URL 已复制到剪贴板：手动打开并登录；"
                         "授权后网关会自动后台换票（最长 3 分钟），完成后点“测试”验证")
                    return
            except Exception as e:  # noqa: BLE001
                emit(f"[ca] 获取授权 URL 失败（服务未运行？）：{e}")
                return
        emit("[ca] 请先启动服务，再点“授权”")

    def refresh_ca_info():
        """ca_info 显示：余额 + 授权状态。读后台缓存（原来 15s+8s，会把界面卡死）。"""
        if not services["ca"].running:
            ca_info.configure(text="● 未启动 · 每日 10M token（3 个免费模型共用） · 凭证自动取自 华为云 CodeArts 桌面端 或 VS Code 插件（huaweicloud.vscode-codebot） · 点「授权」可在浏览器登录，此后自动续期",
                              foreground="#555")
            return
        with _q_lock:
            meta = dict(_q_meta.get("ca") or {})
            snap = dict(_q_data["ca"]) if _q_data.get("ca") else {}
        if snap:
            tb = int(snap.get("total_balance") or 0)
            tq = int(snap.get("total_quota") or 0)
            ua = int(snap.get("used_amount") or 0)
            line = f"✓ 剩余额度 {tb:,} / {tq:,} tokens · 已用 {ua:,}"
        else:
            line = ("✗ 余额查询失败 —— 请点「授权」重新登录" if meta.get("err")
                    else "● 余额查询中…")
        a = snap.get("_auth") or {}
        exch = a.get("exchange") or {}
        if exch.get("state") == "pending":
            # 后台还在轮询换票（最长 3 分钟，官方插件同样语义）
            auth = (f"● 授权换取中 · 已试 {int(exch.get('attempts') or 0)} 轮（最长 3 分钟）"
                    f" · {str(exch.get('error') or '')[:36]}")
        elif exch.get("state") == "timeout":
            auth = f"✗ 授权换取超时 —— {str(exch.get('error') or '')[:48]}"
        elif exch.get("state") == "error":
            auth = f"✗ 授权换取失败 —— {str(exch.get('error') or '')[:48]}"
        elif exch.get("state") == "ok":
            auth = "✓ 授权成功 · OAuth ticket 已换到凭证"
        elif a:
            auth = ("✓ 授权有效" if a.get("ok")
                    else f"✗ 未授权 —— {str(a.get('error') or '')[:40]}")
        else:
            auth = "● 授权状态未知"
        h = snap.get("_health") or {}
        extra = ""
        if h.get("station") == "international":
            extra += " · 国际站 ap-southeast-1"
        pool = (h.get("pool") or {}) if isinstance(h.get("pool"), dict) else {}
        if pool.get("enabled"):
            keys = pool.get("keys") or []
            ok_n = sum(1 for k in keys if not k.get("cooling") and not k.get("off"))
            extra += f" · 号池可用 {ok_n}/{len(keys)}"
        ca_info.configure(text=f"{line}\n{auth}{extra}", foreground="#1a7f37")

    def ca_claim(quiet: bool = False) -> bool:
        """领取华为云每日福利。上游幂等：重复调用仍返回 error_code=0000。"""
        if not services["ca"].running:
            if not quiet:
                emit("[ca] 未运行，无法领取福利")
            return False
        port = ca_port.get().strip() if ca_port.get().strip().isdigit() else "9100"
        res, err = _http_json(f"http://127.0.0.1:{port}/v1/claim",
                              timeout=60, method="POST", data=b"{}")
        if res.get("ok"):
            settings["ca_last_claim"] = time.strftime("%Y-%m-%d")
            save_settings(settings)
            emit("[ca] 自动领取每日福利成功" if quiet else "[ca] 每日福利领取成功")
            ui(refresh_ca_info)
            return True
        if not quiet:
            emit(f"[ca] 领取福利失败：{err or res.get('error') or '未知错误'}")
        return False

    _claim_try = [0.0]

    def _maybe_auto_claim(force: bool = False) -> bool:
        """每天自动领一次。成功即记日期；失败 30 分钟内不重试（避免刷接口）。"""
        if not services["ca"].running:
            return False
        today = time.strftime("%Y-%m-%d")
        if not force:
            if settings.get("ca_last_claim") == today:
                return False
            if time.time() - _claim_try[0] < 1800:
                return False
        _claim_try[0] = time.time()
        return ca_claim(quiet=True)

    def _auto_claim_delayed():
        """服务起来后稍等再领（等凭证/端口就绪）。"""
        time.sleep(3)
        _maybe_auto_claim()

    # ---------------- 凭证状态提示（每个通道一句人话） ----------------
    # 五个通道的凭证都来自「桌面端登录后留下的文件」，网关读文件直连上游，
    # 所以桌面端不必常开。这里把「有没有凭证 / 过没过期 / 能不能关桌面端 /
    # 什么时候要重登」一次讲清楚。
    CRED_NAMES = {"cb": "WorkBuddy", "mc": "MonkeyCode", "ca": "华为云 CodeArts",
                  "rc": "小浣熊", "lo": "Loomy"}

    def _fmt_ms(ms) -> str:
        """毫秒时间戳 → 本地时间字符串"""
        try:
            v = float(ms or 0)
            return time.strftime("%Y-%m-%d %H:%M", time.localtime(v / 1000.0)) if v else "—"
        except Exception:  # noqa: BLE001
            return "—"

    def _fmt_iso(s) -> str:
        """ISO8601（UTC）→ 本地时间字符串"""
        try:
            from datetime import datetime, timezone
            if not s:
                return "—"
            dt = datetime.fromisoformat(str(s).replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.astimezone().strftime("%Y-%m-%d %H:%M")
        except Exception:  # noqa: BLE001
            return str(s)[:16] if s else "—"

    def _left(ts_sec: float) -> str:
        d = (ts_sec - time.time()) / 86400.0
        if d <= 0:
            return "已过期"
        return "不足 1 天" if d < 1 else f"剩约 {int(d)} 天"

    def _cred_cb():
        # 按「使用版本」选凭据文件（auto=取最近活跃），与运行时保持一致
        _st = None if cb_station.get() == "auto" else cb_station.get()
        af = find_cb_auth_file(_st)
        if af is None:
            _lab = WB_STATION_LABEL.get(_st, "")
            return (f"✗ 未找到{_lab}登录凭证（{WB_AUTH_FILES.get(_st, 'workbuddy-desktop*.info')}）"
                    " —— 请打开对应版本桌面端登录一次", "#c0392b")
        try:
            d = json.loads(af.read_text(encoding="utf-8"))
        except Exception as e:  # noqa: BLE001
            return (f"✗ 凭证文件读取失败：{e}", "#c0392b")
        auth = d.get("auth") or {}
        acct = d.get("account") or {}
        exp = float(auth.get("expiresAt") or 0)
        rexp = float(auth.get("refreshExpiresAt") or 0)
        _dom = auth.get("domain") or "-"
        _real = "intl" if any(k in _dom for k in ("workbuddy.ai", "codebuddy.ai")) else "cn"
        who = f"{acct.get('nickname') or '?'} @ {_dom} [{WB_STATION_LABEL.get(_real, '?')}版]"
        now_ms = time.time() * 1000
        if exp and now_ms >= exp - 60_000:
            if rexp and now_ms < rexp:
                return (f"● {who} · 访问令牌刚到期，但刷新令牌有效（{_fmt_ms(rexp)} 前可自动续期）"
                        " —— 正常运行，网关会自动刷新，可以关闭桌面端", "#b8860b")
            return (f"✗ {who} 登录凭证已过期（{_fmt_ms(exp)}）—— 请重新登录该版本 WorkBuddy",
                    "#c0392b")
        return (f"✓ 凭证有效 · {who} · {_fmt_ms(exp)} 到期（{_left(exp / 1000)}）"
                " —— 正常运行，网关会自动续期，可以关闭桌面端", "#1a7f37")

    def _cred_mc():
        base = ""
        try:
            mc = sys.modules.get("monkeycode2openai")
            if mc is not None and mc.CONFIG.get("base_url"):
                # mode 是内部术语（ohmyagent/static）→ 翻成中文，和别的通道文风一致
                _mlab = {"ohmyagent": "官方代理", "static": "静态 key"}.get(
                    mc.CONFIG.get("mode", "static"), mc.CONFIG.get("mode", ""))
                base = f"{mc.CONFIG['base_url']}（{_mlab}）"
        except Exception:  # noqa: BLE001
            pass
        if not base:
            b = monkeycode_upstream_base()
            base = b if b else ""
        ck = Path(os.environ.get("APPDATA") or "") / "com.chaitin.baizhi.monkeycode" / "monkeycode-cookies.json"
        has_ck = ck.is_file() and ck.stat().st_size > 2
        # 会话是否已被上游判为失效（额度跟踪线程会拿到 401）
        ck_err = ""
        try:
            with _q_lock:
                ck_err = str((_q_meta.get("mc") or {}).get("err") or "")
        except Exception:  # noqa: BLE001
            pass
        if not base:
            return ("✗ 未找到上游配置 —— 请打开 MonkeyCode 桌面端登录一次", "#c0392b")
        if not has_ck:
            return (f"✓ 凭证有效 · {base} · 会话文件缺失"
                    " —— 对话正常，可以关闭桌面端；余额/签到不可用（重登桌面端即可）", "#b8860b")
        if "401" in ck_err or "会话" in ck_err or "无效" in ck_err:
            return (f"● 凭证有效 · {base} · 会话已过期"
                    " —— 对话正常，可以关闭桌面端；请重登 MonkeyCode 桌面端恢复余额/签到",
                    "#b8860b")
        return (f"✓ 凭证有效 · {base} · 会话正常"
                " —— 正常运行，网关会自动续期，可以关闭桌面端", "#1a7f37")

    def _cred_ca():
        fp = data_dir() / "ca_codearts.json"
        st = {}
        try:
            if fp.is_file():
                st = json.loads(fp.read_text(encoding="utf-8"))
        except Exception:  # noqa: BLE001
            st = {}
        has_dpop = bool(st.get("refresh_token"))
        tk = st.get("ticket") or {}
        last = st.get("last") if isinstance(st.get("last"), dict) else {}
        c_exp = (last.get("credentials") or {}).get("expiration")
        # 本机 state 还没有时，直接扫登录来源（CodeArts 桌面端 / VS Code 插件）——
        # 两个来源用的是同一套 v10 加密，都能当凭证用。
        srcs = []
        try:
            ca_mod = _core("ca")
            if ca_mod is not None:
                # 用带 TTL 缓存的版本：GUI 每 10s 探测一次，不该每次都 DPAPI 解密
                fn = getattr(ca_mod, "_bootstrap_all_cached", None) or \
                    getattr(ca_mod, "_bootstrap_all", None)
                if fn is not None:
                    srcs = [label for label, _s in (fn() or [])]
        except Exception:  # noqa: BLE001
            srcs = []
        if not has_dpop and not tk.get("access") and not srcs:
            return ("✗ 未找到登录凭证（CodeArts 桌面端 / VS Code 插件 huaweicloud.vscode-codebot）"
                    " —— 请登录一次，或点「授权」", "#c0392b")
        parts = []
        if has_dpop:
            parts.append(f"DPoP 会话有效（{_fmt_iso(c_exp)} 到期 · 网关自动续期）")
        elif srcs:
            parts.append(f"凭证来源 {srcs[0]}（网关会自动接管）")
        else:
            parts.append("DPoP 会话缺失")
        parts.append(f"ticket 有效（{_fmt_iso(tk.get('expires_at'))} 到期）" if tk.get("access")
                     else "ticket 未授权（余额/签到会退用 DPoP）")
        return ("✓ 凭证有效 · " + " · ".join(parts)
                + " —— 正常运行，网关会自动续期，可以关闭桌面端/VS Code"
                  "（但别同时用，令牌会互相顶掉）", "#1a7f37")

    def _cred_rc():
        d = rc_auth.get().strip() or str(Path.home() / ".box-agent" / "config")
        p = Path(d) / "auth.json"
        if not p.is_file():
            return (f"✗ 未找到登录凭证（{p}） —— 请打开小浣熊桌面端登录一次", "#c0392b")
        try:
            j = json.loads(p.read_text(encoding="utf-8"))
        except Exception as e:  # noqa: BLE001
            return (f"✗ 凭证文件读取失败 —— {e}", "#c0392b")
        tok = j.get("access_token") or j.get("token") or j.get("auth_token")
        if not tok:
            return ("✗ 凭证文件里没有 access_token —— 请重新登录小浣熊桌面端", "#c0392b")
        rt = "已备" if j.get("refresh_token") else "缺失"
        return (f"✓ 凭证有效 · access_token 就绪 · refresh_token {rt}"
                " —— 正常运行，401 时网关自动刷新，可以关闭桌面端", "#1a7f37")

    def _cred_lo():
        """Loomy 凭证：优先运行中的内嵌 opencode，其次 Local Storage 的会话。"""
        lo = sys.modules.get("loomy2openai")
        if lo is None:
            return ("● 服务未启动，无法探测凭证 —— 启动服务后自动检测", "#555")
        src, base, key = "", "", ""
        try:
            got = lo._from_opencode()
            if got:
                src, (base, key, _m) = "Loomy 内嵌 opencode", got
            else:
                got = lo._from_local_storage()
                if got:
                    src, (base, key, _m) = "Loomy 本地会话", got
        except Exception as e:  # noqa: BLE001
            return (f"✗ 探测失败 —— {e}", "#c0392b")
        if not key:
            return ("✗ 未找到登录凭证 —— 请打开 Loomy 桌面端登录一次", "#c0392b")
        return (f"✓ 凭证有效 · 来源 {src} · {base} · 会话 {len(key)} 字符"
                " —— 正常运行，可以关闭 Loomy 桌面端（会话失效后需重开登录）", "#1a7f37")

    _cred_targets = {"cb": cb_cred, "mc": mc_cred, "ca": ca_cred, "rc": rc_cred, "lo": lo_cred}
    _cred_probes = {"cb": _cred_cb, "mc": _cred_mc, "ca": _cred_ca, "rc": _cred_rc, "lo": _cred_lo}

    _cred_cache: dict = {}
    _cred_lock = threading.Lock()

    def _probe_creds():
        """后台线程：算出各通道凭证文案。
        注意里面可能有阻塞操作（Loomy 要请求 opencode、扫 leveldb），
        绝不能放在 Tk 线程里跑——那正是界面卡顿的主因。"""
        out = {}
        for key in _cred_probes:
            try:
                out[key] = _cred_probes[key]()
            except Exception as e:  # noqa: BLE001
                out[key] = (f"✗ 凭证状态检测失败：{e}", "#c0392b")
        with _cred_lock:
            _cred_cache.clear()
            _cred_cache.update(out)

    def refresh_creds(verbose: bool = False):
        """Tk 线程：只把缓存好的文案写进标签，零 IO。"""
        with _cred_lock:
            snap = dict(_cred_cache)
        for key, lbl in _cred_targets.items():
            txt, fg = snap.get(key, ("● 检测中…", "#555"))
            lbl.configure(text=f"{CRED_NAMES[key]}：{txt}", foreground=fg)
            if verbose:
                emit(f"[{key}] 凭证：{txt}")

    # ---------------- 实时额度跟踪（MonkeyCode / 华为云 CodeArts） ----------------
    # 后台守护线程按 QUOTA_INTERVAL 秒拉取两通道余额/用量，主线程渲染到 *_quota 行。
    # 取数只走本地服务端点（:9000/v1/wallet · :9100/v1/balance），不直连上游，
    # 因此不额外消耗上游额度、也不与授权逻辑争抢 refresh_token。
    QUOTA_INTERVAL = float(os.environ.get("BUDDYZ_QUOTA_INTERVAL") or 10.0)

    _q_data: dict = {"mc": None, "ca": None, "lo": None}   # 最近一次成功快照
    _q_meta: dict = {"mc": {}, "ca": {}, "lo": {}}         # {"off":bool,"ts":float,"err":str}
    _q_lock = threading.Lock()

    def _q_endpoint(key: str) -> str:
        ent, dflt = {"mc": (mc_port, "9000"), "ca": (ca_port, "9100"),
                     "lo": (lo_port, "9400")}.get(key, (ca_port, "9100"))
        cur = ent.get().strip()
        return f"http://127.0.0.1:{cur if cur.isdigit() else dflt}"

    def _q_probe(key: str) -> None:
        """后台线程：拉取一次额度并写缓存。只做 HTTP，不碰 Tk 控件。"""
        if not services[key].running:
            with _q_lock:
                _q_meta[key] = {"off": True, "ts": time.time(), "err": ""}
            return
        base = _q_endpoint(key)
        err, snap = "", None
        try:
            if key == "mc":
                w, e1 = _http_json(base + "/v1/wallet", timeout=10)
                if e1:
                    err = e1
                elif isinstance(w, dict) and w.get("ok"):
                    snap = dict(w.get("data") or {})
                else:
                    err = str((w or {}).get("error") or "钱包不可用")
                if snap is not None:
                    u, e2 = _http_json(base + "/v1/usage", timeout=5)
                    if not e2 and isinstance(u, dict):
                        snap["_usage"] = u
                    h, e3 = _http_json(base + "/health", timeout=5)
                    if not e3 and isinstance(h, dict):
                        snap["_health"] = h
            elif key == "ca":
                b, e1 = _http_json(base + "/v1/balance", timeout=10)
                if e1:
                    err = e1
                elif isinstance(b, dict) and b.get("ok"):
                    snap = dict(b.get("data") or {})
                else:
                    err = str((b or {}).get("error") or "余额不可用")
                if snap is not None:
                    a, e2 = _http_json(base + "/v1/auth/status", timeout=8)
                    if not e2 and isinstance(a, dict):
                        snap["_auth"] = a
                    h, e3 = _http_json(base + "/health", timeout=5)
                    if not e3 and isinstance(h, dict):
                        snap["_health"] = h
            else:  # lo：Loomy 积分（读本地缓存摘要）
                p, e1 = _http_json(base + "/v1/points", timeout=10)
                if e1:
                    err = e1
                elif isinstance(p, dict) and p.get("ok"):
                    snap = dict(p.get("data") or {})
                else:
                    err = str((p or {}).get("error") or "积分不可用")
        except Exception as e:  # noqa: BLE001
            err = f"{type(e).__name__}: {e}"
        with _q_lock:
            _q_meta[key] = {"off": False, "ts": time.time(), "err": err}
            if snap is not None:
                _q_data[key] = snap

    def _q_pct(used: int, total: int) -> str:
        return f"{used / total * 100:.1f}%" if total else "—"

    def _fmt_quota(key: str):
        """(文本, 颜色)。纯读缓存、无 IO，可在 Tk 线程安全调用。"""
        with _q_lock:
            meta = dict(_q_meta.get(key) or {})
            snap = dict(_q_data[key]) if _q_data.get(key) else None
        if meta.get("off"):
            return ("● 额度跟踪 · 服务未启动", "#555")
        ts = meta.get("ts") or 0
        stamp = time.strftime("%H:%M:%S", time.localtime(ts)) if ts else "—"
        if snap is None:
            msg = (meta.get("err") or "").strip()
            return (f"✗ 额度跟踪 · {msg[:70]}" if msg else "● 额度跟踪 · 等待上游…",
                    "#c0392b" if msg else "#555")
        if key == "mc":
            dtb = int(snap.get("daily_token_balance") or 0)
            dtl = int(snap.get("daily_token_limit") or 0)
            bal = float(snap.get("balance") or 0)
            parts = [f"每日 token 剩余 {dtb:,} / {dtl:,}" if dtl else f"每日 token 余额 {dtb:,}"]
            if dtl:
                parts[0] += f"（{_q_pct(dtb, dtl)}）"
            parts.append(f"积分 {bal / 1000:.2f}")
            u = snap.get("_usage") or {}
            if u:
                parts.append(f"本机今日 {u.get('total', 0):,} tokens / {u.get('requests', 0)} 次")
        elif key == "ca":
            tb = int(snap.get("total_balance") or 0)
            tq = int(snap.get("total_quota") or 0)
            ua = int(snap.get("used_amount") or 0)
            parts = [f"每日 token 剩余 {tb:,} / {tq:,}"
                     + (f"（已用 {ua:,} · {_q_pct(ua, tq)}）" if tq else "")]
            a = snap.get("_auth") or {}
            if a:
                parts.append("授权有效" if a.get("ok") else "未授权")
            h = snap.get("_health") or {}
            if h.get("station") == "international":
                parts.append("国际站")
            pool = (h.get("pool") or {}) if isinstance(h.get("pool"), dict) else {}
            if pool.get("enabled"):
                keys = pool.get("keys") or []
                ok_n = sum(1 for k in keys if not k.get("cooling") and not k.get("off"))
                parts.append(f"号池可用 {ok_n}/{len(keys)}")
        else:  # lo
            bal = int(snap.get("balance") or 0)
            day = int(snap.get("dailyBalance") or 0)
            parts = [f"永久积分 {bal:,}", f"每日积分 {day:,}"]
        head = "Loomy 积分" if key == "lo" else "额度跟踪"
        mark = "✗" if meta.get("err") else "✓"
        line = f"{mark} {head} · " + " · ".join(parts) + f" · 更新 {stamp}"
        return (line, "#b8860b" if meta.get("err") else "#1a7f37")

    def render_quota() -> None:
        """Tk 线程：把缓存渲染到两行额度标签。"""
        try:
            t, fg = _fmt_quota("mc")
            mc_quota.configure(text=t, foreground=fg)
            t, fg = _fmt_quota("ca")
            ca_quota.configure(text=t, foreground=fg)
            t, fg = _fmt_quota("lo")
            lo_quota.configure(text=t, foreground=fg)
        except Exception:  # noqa: BLE001
            pass

    def _q_loop() -> None:
        """后台守护线程：周期性刷新两通道额度并请主线程重渲染。"""
        while not _exiting:
            for k in ("mc", "ca", "lo"):
                try:
                    _q_probe(k)
                except Exception:  # noqa: BLE001
                    pass
            _probe_creds()      # 后台线程里探测（含 HTTP/扫文件），不阻塞 Tk
            ui(render_quota)
            ui(refresh_creds)   # 渲染只读缓存
            try:
                _maybe_auto_claim()   # 跨天后自动补领福利（当天已领则直接返回）
            except Exception:  # noqa: BLE001
                pass
            time.sleep(max(3.0, QUOTA_INTERVAL))

    def _http_test(key, url, fmt) -> bool:
        """返回是否通过（供「测试」按钮变色）"""
        import urllib.request
        try:
            with urllib.request.urlopen(url, timeout=5) as r:
                data = json.loads(r.read().decode("utf-8"))
            emit(f"[{key}] 测试 {url} → {fmt(data)}")
            return True
        except Exception as e:  # noqa: BLE001
            emit(f"[{key}] 测试 {url} 失败：{e}")
            return False

    def _http_test_chat(key, url) -> bool:
        ui(refresh_creds)   # 点「测试」时顺带刷新凭证状态，立刻能看到最新结论
        import urllib.request
        model = (eff_models(key) or ["auto"])[0]
        # WorkBuddy 上游要求首条为 system prompt，否则 400（code 11128）
        msgs = ([{"role": "system", "content": "you are a helpful assistant"}]
                if key == "cb" else []) + [{"role": "user", "content": "hi"}]
        payload = json.dumps({"model": model, "messages": msgs, "max_tokens": 60, "stream": False}).encode("utf-8")
        req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"}, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=60) as r:
                data = json.loads(r.read().decode("utf-8"))
            choices = (data or {}).get("choices") or []
            m = choices[0].get("message", {}) if choices else {}
            msg = m.get("content") or ""
            if not msg and m.get("reasoning_content"):
                msg = "[reasoning] " + str(m.get("reasoning_content"))[:40]
            if not msg:
                msg = "finish=" + str(choices[0].get("finish_reason", "?")) if choices else "no choices"
            emit(f"[{key}] 测试 {url} → chat OK({model}) · {msg[:60]}")
            return True
        except Exception as e:  # noqa: BLE001
            emit(f"[{key}] 测试 {url} 失败：{e}")
            return False

    def detect_env():
        emit("──── 本地环境检测 ────")
        # WorkBuddy 国内/国际是两个独立安装，各占一行、各探各的
        for key, skey, st, name in (
                ("cb", "wb_path_cn", "cn", "WorkBuddy(国内)"),
                ("cb", "wb_path_intl", "intl", "WorkBuddy(国际)"),
                ("mc", "mc_path", None, "MonkeyCode"),
                ("ca", "ca_path", None, "CodeArts(桌面端/VS Code插件)"),
                ("rc", "rc_path", None, "商汤小浣熊"),
                ("lo", "lo_path", None, "Loomy")):
            entry = cb_path_cn if skey == "wb_path_cn" else (
                cb_path_intl if skey == "wb_path_intl" else
                {"mc": mc_path, "rc": rc_path, "lo": lo_path}.get(key, ca_path))
            cur = entry.get().strip()
            if not cur:
                kind = {"cb": "wb", "mc": "mc", "rc": "rc", "lo": "lo"}.get(key, "ca")
                found = find_install(kind, st)
                if found:
                    settings[skey] = found
                    save_settings(settings)
                    set_install_path(key, found, st)
                    cur = found
            ok = bool(cur) and Path(cur).exists()
            odd = ""
            if ok and key == "ca":
                # ca 有两个来源，标一下命中的是哪一个
                odd = "（华为云桌面端）" if "codearts" in Path(cur).name.lower() else "（VS Code 插件）"
            emit(f"{name} 程序位置: {'✓ ' + cur + odd if ok else '✗ 未找到（可点「浏览…」指定 exe 或文件夹）'}")
        # Raccoon auth check
        rc_auth_dir = rc_auth.get().strip() or str(Path.home() / ".box-agent" / "config")
        rc_auth_file = Path(rc_auth_dir) / "auth.json"
        rc_ok = rc_auth_file.is_file()
        emit(f"Raccoon 凭据:     {'✓ ' + str(rc_auth_file) if rc_ok else '✗ 未找到 auth.json（请先用桌面端登录一次）'}")
        _ui_cb_info()
        # 两个版本各报一行（两版 auth 文件同目录不同名，可同时登录）
        for _st in ("cn", "intl"):
            _s2 = read_cb_summary(_st)
            _lab = WB_STATION_LABEL[_st]
            if _s2.get("found") and "error" not in _s2:
                emit(f"WorkBuddy({_lab}) : ✓ {_s2['nickname']} / {_s2['enterprise']} · "
                     f"{'token 已过期(将自动刷新)' if _s2['expired'] else 'token 有效'} · "
                     f"域 {_s2['domain']}")
            elif _s2.get("found"):
                emit(f"WorkBuddy({_lab}) : ✗ 读取失败 {_s2.get('error')}")
            else:
                emit(f"WorkBuddy({_lab}) : ✗ 未登录（{WB_AUTH_FILES[_st]} 不存在）")
        emit(f"Python 依赖:      {'✓ 齐全' if not missing_deps() else '✗ 缺失: ' + ' '.join(missing_deps())}")
        mc_base = monkeycode_upstream_base()
        emit(f"MonkeyCode 上游: {'✓ ' + mc_base if mc_base else '✗ 未找到（config.json 无 models[0].api_key）'}")
        ui(refresh_mc_info)
        emit("────────────────────")

    def refresh_cb_credits():
        """cb_info 追加第3行剩余额度（仅服务运行时查询）"""
        try:
            if not services["cb"].running:
                return
            import urllib.request
            base = cb_url.get().rstrip("/")
            with urllib.request.urlopen(base + "/credits", timeout=15) as r:
                d = json.loads(r.read().decode("utf-8"))
            line = (f"剩余额度 {d.get('remain', 0):.2f} credits "
                    f"(总数 {d.get('total', 0):.0f} · 已用 {d.get('used', 0):.2f})")
            cur = cb_info.cget("text")
            lines = [l for l in cur.split("\n") if not l.startswith("剩余额度")]
            cb_info.configure(text="\n".join(lines + [line]))
        except Exception:
            pass

    def _ui_cb_info(_s: dict | None = None):
        """显示两个版本**各自**的账号状态，并标出当前生效的那一个。

        两版 auth 文件同目录不同名，因此可以同时登录 —— 这里两行都报出来，
        免得用户看不出"国内那行到底有没有登录成功"。
        """
        want = cb_station.get()
        # 生效版本：**以用户的选择为准**（选 cn/intl 就一定是它）；
        # 只有 auto 时才按登录文件推测 —— 之前 auto 分支的优先级写在了前面，
        # 导致"选了国内、显示还是国际"，看着像没切。
        active = want if want in ("cn", "intl") else next(
            (st for st in ("intl", "cn") if read_cb_summary(st).get("found")), None)
        rows = []
        for st in ("cn", "intl"):
            s = read_cb_summary(st)
            lab = WB_STATION_LABEL[st]
            # 用 ">" 标出当前生效的那一行（原来用 ★，已去掉）
            mark = ">" if st == active else "　"      # 全角空格对齐
            if s.get("found") and "error" not in s:
                exp = (time.strftime("%Y-%m-%d %H:%M", time.localtime(s["expires_at"] / 1000))
                       if s.get("expires_at") else "?")
                rows.append(f"{mark}[{lab}] {s['nickname']} · {s['domain']} · "
                            f"token {'已过期,将自动刷新' if s['expired'] else f'有效至 {exp}'}")
            elif s.get("found"):
                rows.append(f"{mark}[{lab}] 凭据文件异常：{s.get('error')}")
            else:
                rows.append(f"{mark}[{lab}] 未登录（{WB_AUTH_FILES[st]} 不存在）")
        rows.append(f"当前使用：{'自动（跟随登录：' + (WB_STATION_LABEL.get(active, '无') if active else '无') + '）' if want == 'auto' else WB_STATION_LABEL.get(want, want)}"
                    f"　> = 生效版本")

        def apply():
            cb_info.configure(text="\n".join(rows), foreground="#1a7f37")
        ui(apply)

    _status_seen: dict = {}

    def _ui_status(key, kind, text):
        if _status_seen.get(key) == (kind, text):   # 状态没变就不重画（原来每 800ms 无脑 configure）
            return
        _status_seen[key] = (kind, text)

        def apply():
            color = {"run": "#1a7f37", "error": "#c0392b", "off": "#999"}.get(kind, "#999")
            mapping = {"cb": (cb_status, cb_led), "mc": (mc_status, mc_led), "ca": (ca_status, ca_led), "rc": (rc_status, rc_led), "lo": (lo_status, lo_led)}
            lab, led = mapping.get(key, (cb_status, cb_led))
            lab.configure(text=text, foreground=color)
            led.itemconfigure("o",
                fill={"run": "#22c55e", "error": "#ef4444", "off": "#9ca3af"}.get(kind, "#999"))
            running = any(s.running for s in services.values())
            global_status.configure(foreground="#22c55e" if running else ("#ef4444" if any(
                s.error for s in services.values()) else "#9ca3af"))
        ui(apply)

    # ---------------- 队列泵 & LED 轮询 ----------------
    _log_rows = [0]          # 已插入行数（避免每行都做 log_text.index()）

    def _append_logs(lines: list):
        """一批日志只 configure 两次、只 see 一次。
        原来是每行 configure×2 + index() + see()，日志一多就明显卡。"""
        if len(lines) > 200:                 # 单次最多插 200 行
            lines = lines[-200:]
        log_text.configure(state="normal")
        for ln in lines:
            log_text.insert("end", ln + "\n", log_line_tag(ln))
        _log_rows[0] += len(lines)
        if _log_rows[0] > 3000:              # 只在需要裁剪时才真正数一次行数
            try:
                total = int(log_text.index("end-1c").split(".")[0])
            except Exception:  # noqa: BLE001
                total = _log_rows[0]
            drop = max(0, total - 2500)
            if drop:
                log_text.delete("1.0", f"{drop + 1}.0")
            _log_rows[0] = total - drop
        log_text.see("end")
        log_text.configure(state="disabled")

    def pump():
        logs, calls = [], []
        try:
            while True:
                kind, payload = log_q.get_nowait()
                if kind == "log":
                    logs.append(payload)
                else:
                    calls.append(payload)
        except queue.Empty:
            pass
        if calls:
            for fn, args in calls:
                try:
                    fn(*args)
                except Exception as e:  # noqa: BLE001
                    print(f"[ui-error] {e}")
        if logs:
            _append_logs(logs)
        root.after(150, pump)

    def poll_status():
        for key, svc in services.items():
            if svc.running:
                el = int(time.time() - (svc.started_at or time.time()))
                _ui_status(key, "run", f"运行中 · {el}s")
            elif svc.error:
                _ui_status(key, "error", f"异常：{svc.error[:60]}")
            else:
                _ui_status(key, "off", "未启动")
        root.after(1500, poll_status)

    _exiting = False

    def real_exit():
        nonlocal _exiting
        if _exiting:
            return
        _exiting = True
        # 先存窗口状态：后面要停服务/停托盘，万一哪步卡住也保证状态不丢
        save_window_state(root, _COLLAPSE_STATE)
        _persist()
        try:                                  # 冲刷日志缓冲
            if _logf.get("fh") is not None and not _logf["fh"].closed:
                _logf["fh"].flush()
                _logf["fh"].close()
        except Exception:  # noqa: BLE001
            pass
        emit("正在退出 …")
        for svc in services.values():
            try:
                svc.stop(6)
            except Exception:
                pass
        try:
            if tray_icon is not None:
                tray_icon.stop()
        except Exception:
            pass
        if smoke:
            print("UISMOKE OK")
        root.destroy()

    def on_close():
        # 右上角 ×：有托盘则缩小到托盘（服务继续运行），否则真正退出。
        # 两种情况都要存窗口状态 —— 缩到托盘后若被强杀，下次也应记得上次的样子。
        save_window_state(root, _COLLAPSE_STATE)
        if tray_icon is not None:
            root.withdraw()
            emit("已最小化到系统托盘，服务继续运行（退出请用托盘右键菜单 → 退出）")
        else:
            real_exit()

    root.protocol("WM_DELETE_WINDOW", on_close)

    _last_refresh = [0.0]

    def _schedule_refresh(delay: float = 10.0):
        """延迟后台刷新模型存活（去重：120 秒内只跑一次）。"""
        if time.time() - _last_refresh[0] < 120:
            return
        _last_refresh[0] = time.time()

        def _run():
            time.sleep(delay)
            try:
                bases = {}
                for k, ent, dflt in (("mc", mc_port, 9000), ("ca", ca_port, 9100), ("lo", lo_port, 9400)):
                    try:
                        p = int(ent.get())
                    except ValueError:
                        p = dflt
                    if services.get(k) and services[k].running:
                        bases[k] = f"http://127.0.0.1:{p}/v1"
                refresh_models_startup(settings, emit, bases)
            except Exception as e:  # noqa: BLE001
                emit(f"[models] 启动刷新失败：{e}")
        threading.Thread(target=_run, daemon=True).start()

    # ---------------- 启动初始化（后台） ----------------
    def init_bg():
        """启动初始化（后台线程），**分两段**。

        ① 轻活：解包内嵌文件、模型名提示、缺依赖提示 —— 几毫秒，尽早做。
        ② 重活：`detect_env()` 要扫 Program Files/注册表、`_probe_creds()` 要
           DPAPI 解密 + 读 sqlite、`create_tray()` 要起托盘 —— 这些会持续抢
           CPU/GIL/磁盘，而窗口刚出现时正需要这些资源做首屏布局与绘制。
           所以**延后 ~1.2s** 再干，用户看到的是"窗口立刻出来"，而不是
           "点开卡住一秒多"。（原来是全部挤在一起，这正是打开卡的主因。）
        """
        # 先让首屏画完再干任何初始化：`missing_deps()` 会 import
        # fastapi/uvicorn/cryptography/pystray 等重模块，**首次 import 会长时间持
        # GIL**，正好和首屏布局绘制撞上 —— 实测那 200~300ms 的"卡"主要来自这里。
        _mark("init_bg 等待首屏让出 1.2s")
        time.sleep(1.2)
        _mark("init_bg 开始（轻活）")
        try:
            if not is_frozen() and missing_deps():
                emit("[deps] 检测到缺失模块，后台自动安装…")
                install_deps(emit)
            refresh_model_hints()
            materialize(emit)
        except Exception as e:  # noqa: BLE001
            emit(f"[init] 初始化失败：{type(e).__name__}: {e}")

        _mark("init_bg 轻活完成")
        try:
            detect_env()
            _probe_creds()                    # 后台探测
            ui(lambda: refresh_creds(True))   # 再在 Tk 线程渲染 + 写日志
            _validate_models()
            create_tray()
            if autostart_var.get() and not smoke:
                emit("[auto] 已开启自动启动 …")
                start_all()
            _schedule_refresh()
            # 实时额度跟踪线程（MonkeyCode / 华为云）
            threading.Thread(target=_q_loop, daemon=True).start()
            _mark("init_bg 重活完成")
        except Exception as e:  # noqa: BLE001
            emit(f"[init] 初始化失败：{type(e).__name__}: {e}")

    threading.Thread(target=init_bg, daemon=True).start()
    pump()
    poll_status()
    _refresh_urls()
    # 读 Hermes config.yaml 也算 IO：推迟到首屏画完再做（它要直接改控件，
    # 只能留在 Tk 线程，所以用 after 延后而不是丢后台线程）
    root.after(800, refresh_hermes_status)
    if smoke:
        # 自检模式：不显示窗口，构建完成后自动退出（验证 UI 可正常构建）
        # 并且**真的打开一次号池对话框**——那是本次改动最大的新 UI 代码，
        # 只构建主窗口覆盖不到它。任何异常都会打成 UISMOKE DIALOG FAIL。
        root.withdraw()

        def _dlg_smoke():
            # ── 三通道「使用版本」控件必须存在且可用（国内/国际/自动）──
            def _texts(w):
                out = []
                try:
                    t = w.cget("text")
                    if t:
                        out.append(str(t))
                except Exception:      # noqa: BLE001  非 ttk 控件没有 text
                    pass
                for _c in w.winfo_children():
                    out += _texts(_c)
                return out

            _txt = _texts(root)
            for _name, _var in (("cb", cb_station), ("mc", mc_station), ("ca", ca_station)):
                _ok = _var.get() in ("auto", "cn", "intl")
                print(f"UISMOKE STATION {_name}={_var.get()} {'ok' if _ok else 'BAD'}")
            _need = ("版本", "自动", "国内", "国际",
                     "程序位置(国内)", "程序位置(国际)")
            _miss = [t for t in _need if not any(t in x for x in _txt)]
            print("UISMOKE STATION UI " + ("ok（标题行版本选择+双路径框都在）"
                                          if not _miss else f"MISSING {_miss}"))

            # ── 整窗右侧滚动条 ──
            try:
                root.update_idletasks()
                _bb = canvas.bbox("all")
                _ch = canvas.winfo_height()
                _cw = canvas.winfo_width()
                _ok = (bool(_bb) and (_bb[3] - _bb[1]) > 0 and int(_cw) > 0
                       and str(vsb.cget("orient")) == "vertical"
                       and len(canvas.find_all()) >= 1)
                print(f"UISMOKE SCROLL {'ok' if _ok else 'BAD'} "
                      f"(内容 {_bb[3] - _bb[1] if _bb else 0}px / 视口 {_ch}px, "
                      f"需要滚动={'是' if (_bb and _bb[3] > _ch) else '否'})")
            except Exception as _e:      # noqa: BLE001
                print(f"UISMOKE SCROLL BAD ({type(_e).__name__}: {_e})")

            # ── 字号固定（已移除"界面字号"调节功能）──
            try:
                _no_bar = not any("界面字号" in _t for _t in _txt)
                _ok = (F_UI.cget("size") == UI_BASE_SIZE
                       and F_MONO.cget("size") == MONO_BASE_SIZE and _no_bar)
                print(f"UISMOKE FONTFIXED {'ok' if _ok else 'BAD'} "
                      f"(固定 界面{F_UI.cget('size')}pt / 等宽{F_MONO.cget('size')}pt，"
                      f"调节入口已移除={_no_bar})")
            except Exception as _e:      # noqa: BLE001
                print(f"UISMOKE FONTFIXED BAD ({type(_e).__name__}: {_e})")

            # ── 字体确实全局统一（不依赖已去掉的 option_add("*Font")）──
            # 现场新建一个不带 font 的 ttk.Label，看它实际落到什么字体上；
            # 只有它 == TkDefaultFont == F_UI 才说明"没写 font 的控件"也跟着统一。
            try:
                _probe = ttk.Label(root, text="font-probe")
                _probe.update_idletasks()
                _pf = _probe.cget("font")
                _tst = _tkfont.Font(font=_pf) if _pf else None
                _def = _tkfont.nametofont("TkDefaultFont")
                _ok = (F_UI.cget("family") == "Microsoft YaHei UI"
                       and F_UI.cget("size") == UI_BASE_SIZE
                       and F_MONO.cget("family") == "Consolas"
                       and _def.cget("family") == "Microsoft YaHei UI"
                       and _def.cget("size") == UI_BASE_SIZE
                       and (_tst is None
                            or (_tst.cget("family") == "Microsoft YaHei UI"
                                and _tst.cget("size") == UI_BASE_SIZE)))
                _tdesc = (f"{_tst.cget('family')}/{_tst.cget('size')}pt"
                          if _tst else f"跟随默认({_def.cget('family')}/"
                                       f"{_def.cget('size')}pt)")
                print(f"UISMOKE FONTUNIFIED {'ok' if _ok else 'BAD'} "
                      f"(界面 {F_UI.cget('family')}/{F_UI.cget('size')}pt · "
                      f"未指定字体的控件 → {_tdesc})")
                _probe.destroy()
            except Exception as _e:      # noqa: BLE001
                print(f"UISMOKE FONTUNIFIED BAD ({type(_e).__name__}: {_e})")

            # ── 标题折叠（通道 1~5：点箭头只留标题，且下面的内容要向上补位）──
            # 光"隐藏内容"是不够的：折叠的意义是**省空间**，所以必须同时验证
            #   ① 折叠后只剩标题栏
            #   ② 紧邻的下一个面板 y 坐标**变小**（真的上移了）
            #   ③ canvas 滚动区高度**变小**（滚动条也跟着收起，不是"藏起来还占位"）
            #   ④ 展开后全部还原
            try:
                _pairs = (("1", cbf, mcf), ("2", mcf, caf), ("3", caf, rcf),
                          ("4", rcf, lof), ("5", lof, hrf))
                _rep = []
                # uismoke 下窗口是 withdraw 状态，Tk **跳过真实几何计算** →
                # winfo_y / canvas.bbox 会停在旧值（这也是最初测不出问题的原因）。
                # 临时 deiconify 让 Tk 真正布局；构建期设的 alpha=0 还在，
                # 所以窗口虽然映射了但完全透明，不会闪出来。
                root.deiconify()
                for _ in range(4):          # 多跑几轮让布局收敛：第一轮的值还不可靠
                    root.update_idletasks()
                    root.update()
                # **先归位**：启动会恢复上次的折叠状态，若某个面板本来就是折叠的，
                # 下面的"折叠"操作实际会变成"展开"，断言全反（实测踩过）。
                # 所以断言前先把所有面板统一恢复到"展开"这个已知前提。
                for _tag, _lf, _nx in _pairs:
                    if _COLLAPSE_STATE.get(str(_lf)) and _COLLAPSE.get(str(_lf)):
                        _COLLAPSE[str(_lf)]()
                        root.update_idletasks()
                root.update()
                # 再"预热"一整遍（折叠+展开每个面板）——
                # 否则第一个面板拿到的基准是"布局尚未收敛"的值，会被误判成没还原。
                for _tag, _lf, _nx in _pairs:
                    _tf = _COLLAPSE.get(str(_lf))
                    if _tf:
                        _tf()
                        root.update_idletasks()
                        _tf()
                        root.update_idletasks()
                # 真实等待一下：WorkBuddy 面板的说明文字要换行，Tk 需多轮才能定高，
                # 否则第一个被测面板的"基准"偏小，会被误判成"没还原"。
                for _ in range(3):
                    root.update_idletasks()
                    root.update()
                    time.sleep(0.08)
                for _tag, _lf, _nxt in _pairs:
                    _tg = _COLLAPSE.get(str(_lf))
                    if _tg is None:
                        _rep.append(f"{_tag}=无开关")
                        continue
                    # 取基准前先强制同步一次：否则 scrollregion 还是"上一次应用"的
                    # 陈旧值（基准测得偏小，导致误判展开后没还原）。
                    _force_sync_size()
                    root.update_idletasks()
                    _n0 = len([w for w in _lf.winfo_children() if w.winfo_manager()])
                    _y0, _r0 = _nxt.winfo_y(), _lf.winfo_reqheight()
                    _h0 = (canvas.bbox("all") or (0, 0, 0, 0))[3]
                    _ih0 = inner.winfo_reqheight()       # 内容总高（省空间的直接指标）
                    _lg0 = lf.winfo_height()             # 日志区高度
                    _tg()                                   # 折叠
                    root.update_idletasks()
                    root.update()
                    _n1 = len([w for w in _lf.winfo_children() if w.winfo_manager()])
                    _y1, _r1 = _nxt.winfo_y(), _lf.winfo_reqheight()
                    _force_sync_size()
                    root.update_idletasks()
                    root.update()
                    _h1 = (canvas.bbox("all") or (0, 0, 0, 0))[3]
                    _ih1 = inner.winfo_reqheight()
                    _lg1 = lf.winfo_height()
                    _tg()                                   # 展开
                    root.update_idletasks()
                    root.update()
                    _force_sync_size()
                    root.update_idletasks()
                    root.update()
                    _n2 = len([w for w in _lf.winfo_children() if w.winfo_manager()])
                    _y2, _r2 = _nxt.winfo_y(), _lf.winfo_reqheight()
                    _h2 = (canvas.bbox("all") or (0, 0, 0, 0))[3]
                    _ih2 = inner.winfo_reqheight()
                    # 判定：①只剩标题 ②下面面板真上移 ③面板真收缩
                    #      ④**内容总高变小**（真省出空间，不是只藏起来）
                    #      ⑤滚动区不变大 ⑥展开后全部还原
                    _ok = (_n0 > 1 and _n1 == 1
                           and _y1 < _y0 and _r1 < _r0 and _ih1 < _ih0
                           and _h1 <= _h0
                           and _lg1 >= _lg0          # 省出的空间归日志，不留底色空白
                           and _y2 == _y0 and _r2 == _r0 and _h2 == _h0
                           and _ih2 == _ih0)
                    _rep.append(f"{_tag}={'ok' if _ok else 'BAD'}"
                                + ("" if _ok else
                                   f"(剩{_n1} y{_y0}→{_y1}→{_y2}"
                                   f" 面板高{_r0}→{_r1}→{_r2}"
                                   f" 内容高{_ih0}→{_ih1}→{_ih2}"
                                   f" 日志{_lg0}→{_lg1}"
                                   f" scr{_h0}→{_h1}→{_h2})"))
                root.withdraw()          # 断言完毕，恢复 uismoke 的隐藏状态
                print("UISMOKE COLLAPSE " + " ".join(_rep))
            except Exception as _e:      # noqa: BLE001
                print(f"UISMOKE COLLAPSE BAD ({type(_e).__name__}: {_e})")

            # ── 各通道状态文案文风一致（对齐 WorkBuddy 模板）──
            # 规则：✓/●/✗ 开头 · 必须带「 —— 一句人话」· 分隔符统一 " · " · 无对齐双空格
            try:
                import re as _re
                _probes = [("cb", _cred_cb), ("mc", _cred_mc),
                           ("ca", _cred_ca), ("rc", _cred_rc)]
                # lo 的探测在模块已加载时会去连本地 opencode，避免在 Tk 线程里等它
                if "loomy2openai" not in sys.modules:
                    _probes.append(("lo", _cred_lo))
                _bad = []
                for _k, _fn in _probes:
                    try:
                        _txt, _fg = _fn()
                    except Exception as _e:      # noqa: BLE001
                        _bad.append(f"{_k}=调用异常({type(_e).__name__})")
                        continue
                    _t = str(_txt)
                    _p = []
                    if not _re.match(r"^[✓●✗] ", _t):
                        _p.append("缺前缀")
                    if " —— " not in _t:
                        _p.append("缺提示语")
                    if "  " in _t:
                        _p.append("双空格")
                    if _re.search(r"[^ ]·|·[^ ]", _t):
                        _p.append("分隔符非' · '")
                    if _p:
                        _bad.append(f"{_k}[{'+'.join(_p)}]")
                    print(f"UISMOKE TEXT {_k}: {_t[:120]}")
                print("UISMOKE TEXTSTYLE " + ("ok（各通道文风一致）" if not _bad
                                              else "BAD " + " ".join(_bad)))
            except Exception as _e:      # noqa: BLE001
                print(f"UISMOKE TEXTSTYLE BAD ({type(_e).__name__}: {_e})")

            # ── 标题下的信息行/额度行：前缀与分隔符也要统一 ──
            try:
                import re as _re
                _bad2 = []
                _rows = (("cb_info", cb_info), ("mc_info", mc_info), ("ca_info", ca_info),
                         ("mc_quota", mc_quota), ("ca_quota", ca_quota), ("lo_quota", lo_quota))
                for _nm, _lbl in _rows:
                    for _line in str(_lbl.cget("text") or "").split("\n"):
                        _line = _line.strip()
                        if not _line:
                            continue
                        # cb_info 是"双账号列表"：版本行形如 >[国际] ... / 　[国内] ...
                        # （> 标出生效版本，全角空格是不生效版本）；末行是"当前使用：…"。
                        # 这些都是列表本身，不是状态行 → 豁免前缀规则。
                        if _line.startswith((">", "[", "　", "当前使用")):
                            continue
                        _p = []
                        if not _re.match(r"^[✓●✗]", _line):
                            _p.append("缺前缀")
                        if "★" in _line:
                            _p.append("残留★标记（已废弃）")
                        if "  " in _line:
                            _p.append("双空格")
                        if _re.search(r"[^ ]·|·[^ ]", _line):
                            _p.append("分隔符非' · '")
                        if _p:
                            _bad2.append(f"{_nm}['{_line[:22]}'|{'+'.join(_p)}]")
                            print(f"UISMOKE INFOLINE {_nm}: {_line[:100]!r}")
                # 整窗扫一遍：★ 标记已废弃，任何可见文案里都不该再有
                _star = [t for t in _txt if "★" in t]
                print("UISMOKE NOSTAR " + ("ok（已无 ★ 标记）" if not _star
                                          else "BAD " + " | ".join(_star[:4])))

                print("UISMOKE INFOSTYLE " + ("ok（信息行/额度行一致）" if not _bad2
                                              else "BAD " + " ".join(_bad2)))
            except Exception as _e:      # noqa: BLE001
                print(f"UISMOKE INFOSTYLE BAD ({type(_e).__name__}: {_e})")

            # ── 窗口状态持久化（尺寸/位置/折叠）──
            try:
                # 折叠两个面板 → 记下状态 → 模拟"重启"读回 → 验证能恢复。
                # 注意：启动时会**恢复上次的折叠状态**，所以这里不能假定初始是展开的
                # —— 否则"折叠"实际变成了"展开"，断言就成了假阴性。
                for _lf in (cbf, caf):
                    if _COLLAPSE_STATE.get(str(_lf)):
                        _COLLAPSE[str(_lf)]()
                        root.update_idletasks()
                _COLLAPSE[str(cbf)]()
                root.update_idletasks()
                _COLLAPSE[str(caf)]()
                root.update_idletasks()
                save_window_state(root, _COLLAPSE_STATE)
                _saved = load_window_state()
                _ok = (bool(_saved.get("collapsed", {}).get(str(cbf)))
                       and bool(_saved.get("collapsed", {}).get(str(caf)))
                       and int(_saved.get("w") or 0) > 0 and int(_saved.get("h") or 0) > 0)
                print(f"UISMOKE WINSTATE {'ok' if _ok else 'BAD'} "
                      f"(尺寸 {_saved.get('w')}x{_saved.get('h')} · "
                      f"位置 +{_saved.get('x')}+{_saved.get('y')} · "
                      f"折叠 {sum(1 for v in (_saved.get('collapsed') or {}).values() if v)} 个)")
                # 还原，别影响后面的断言
                _COLLAPSE[str(cbf)]()
                _COLLAPSE[str(caf)]()
                root.update_idletasks()
            except Exception as _e:      # noqa: BLE001
                print(f"UISMOKE WINSTATE BAD ({type(_e).__name__}: {_e})")

            # ── resize 压测：模拟拖拽窗口，量化"每次重排"的耗时 ──
            # 拖拽窗口时 <Configure> 会连发几十上百次，若每次都让 Tk 重排整棵
            # 控件树就会卡。这里连续改高度并强制 update，统计每次的平均耗时。
            try:
                root.deiconify()
                for _ in range(2):
                    root.update_idletasks()
                    root.update()
                _geom0 = root.winfo_geometry()
                _sizes = list(range(700, 1120, 20))
                # 模式 A：每次 resize 都同步 update（用户拖拽时的最差情况）
                _t0 = time.perf_counter()
                for _h in _sizes:
                    root.geometry(f"900x{_h}")
                    root.update_idletasks()
                    root.update()
                _perA = (time.perf_counter() - _t0) / max(1, len(_sizes)) * 1000
                _cost = getattr(_do_sync_size, "cost", 0.0)
                # 模式 B：快连改尺寸、中途不 update，最后一次 update
                #（真实拖拽是事件密集的，靠 40ms 去抖合并 —— 这才是实际体验）
                _t1 = time.perf_counter()
                for _h in _sizes:
                    root.geometry(f"900x{_h}")
                root.update_idletasks()
                root.update()
                _dtB = time.perf_counter() - _t1
                # 经验线：单次全量重排 < 25ms ≈ 跟手；> 60ms 会有明显拖影
                _verdict = "流畅" if _perA < 25 else ("尚可" if _perA < 60 else "卡顿")
                # 模式 C：不改尺寸、只空转 update —— 区分"重排成本"与"update 顺带
                # 执行的其他周期任务（日志泵/状态轮询）成本"
                _t2 = time.perf_counter()
                for _ in range(len(_sizes)):
                    root.update_idletasks()
                    root.update()
                _perC = (time.perf_counter() - _t2) / max(1, len(_sizes)) * 1000
                # 模式 D：只改高度（宽度不变）—— 纵向 resize 不需要 x 方向重排
                _t3 = time.perf_counter()
                for _h in _sizes:
                    root.geometry(f"900x{_h}")
                    root.update_idletasks()
                    root.update()
                _perD = (time.perf_counter() - _t3) / max(1, len(_sizes)) * 1000
                # 模式 E：只改宽度（高度不变）
                _t4 = time.perf_counter()
                for _w in range(820, 1240, 20):
                    root.geometry(f"{_w}x900")
                    root.update_idletasks()
                    root.update()
                _perE = (time.perf_counter() - _t4) / 21 * 1000
                try:                      # 压测改过尺寸 → 恢复，别影响后续断言
                    root.geometry(f"{_geom0}"); root.update_idletasks(); root.update()
                except Exception:      # noqa: BLE001
                    pass
                # 判据用**单维度**：用户拖窗口边只改一个维度，实测 3ms 级；
                # 模式 A 每次 geometry 同时请求宽+高，会触发 Tk 完整重算（~90ms），
                # 那是压测写法的问题，不代表真实拖拽。
                _worst = max(_perD, _perE)
                _v2 = "流畅" if _worst < 25 else ("尚可" if _worst < 60 else "卡顿")
                print(f"UISMOKE RESIZE {'ok' if _worst < 60 else 'BAD'} "
                      f"(纯纵向 {_perD:.1f}ms / 纯横向 {_perE:.1f}ms → {_v2}；"
                      f"空转 {_perC:.1f}ms；重排代码 {_cost:.1f}ms；"
                      f"宽高同改 {_perA:.1f}ms（压测写法，非真实拖拽）)")
                root.withdraw()
            except Exception as _e:      # noqa: BLE001
                print(f"UISMOKE RESIZE BAD ({type(_e).__name__}: {_e})")

            if not POOL_FEATURE:
                # 屏蔽模式：断言 UI 里**找不到**号池入口，且两个开关恒为 False。
                # 这是防"漏屏蔽"的回归 —— 只构建主窗口就能覆盖。
                leaked = sorted({t for t in _txt if "号池" in t})
                print("UISMOKE POOL LEAK: " + " | ".join(leaked) if leaked
                      else "UISMOKE POOL OFF (UI 无号池入口)")
                print(f"UISMOKE POOL VARS mc={bool(mc_pool_on.get())} "
                      f"ca={bool(ca_pool_on.get())}")
                # 仍构建对话框，只为覆盖那段代码不腐烂
            for _k in ("mc", "ca"):
                try:
                    pool_dialog(_k)
                    for _w in list(root.winfo_children()):
                        if isinstance(_w, tk.Toplevel):
                            _w.destroy()
                    print(f"UISMOKE DIALOG OK {_k}")
                except Exception as _e:  # noqa: BLE001
                    print(f"UISMOKE DIALOG FAIL {_k}: {type(_e).__name__}: {_e}")

            # 自检跑完直接销毁窗口退出。**不调 real_exit**：那条路径要做落盘、
            # 停托盘等收尾，自检里既没必要、实测还会卡住（白等兜底超时）。
            # 也**不写窗口状态**：自检期间改过尺寸、折叠过面板，落盘会把
            # 真实用户下次启动的样子搞乱。
            print("UISMOKE OK")
            try:
                root.destroy()
            except Exception:      # noqa: BLE001
                pass

        root.after(1200, _dlg_smoke)
        # 上面 destroy 之后 mainloop 即返回；这个超时只是"断言把窗口搞坏/挂住"时的兜底
        root.after(20000, real_exit)
    # Tk 创建控件只是"注册 Tcl 对象"，真正的布局/字体度量/绘制发生在 idle 阶段。
    # 所以这里先强制跑一次 update_idletasks —— 这才是"打开界面要等的那一下"。
    _mark("UI 注册完毕，开始首次布局")
    root.update_idletasks()
    _mark("首次布局+绘制完成（真实重活）")
    # 位置/最大化/折叠状态统一在这里恢复：此时控件已建好、几何已确定。
    try:
        if _ws.get("zoomed"):
            root.state("zoomed")                       # 最大化
        else:
            x, y = int(_ws.get("x") or 0), int(_ws.get("y") or 0)
            if x or y:
                root.geometry(f"+{x}+{y}")
    except Exception:          # noqa: BLE001
        pass
    # 无论恢复成什么样，都拉回显示器工作区（防止上次的位置在外接屏上、现已拔掉）
    clamp_window_to_screen(root)
    # 恢复折叠：只折叠"上次是折叠态"的面板
    for _k, _v in (_ws.get("collapsed") or {}).items():
        if _v and _k in _COLLAPSE:
            try:
                _COLLAPSE[_k]()
            except Exception:  # noqa: BLE001
                pass
    _force_sync_size()
    if not smoke:
        try:
            root.attributes("-alpha", 1.0)   # 一次性显出完整界面
        except Exception:      # noqa: BLE001
            pass
    root.mainloop()
    # mainloop 仅在 real_exit→root.destroy 后返回；强制结束进程，
    # 防止托盘/第三方线程残留导致控制台黑框不退
    if _exiting:
        os._exit(0)


